import { useEffect, useState } from "react";

import { artexFetch, useArtexQuery } from "@/api/artex";
import { CodexGearLg, CodexGlobe, CodexRailScheduled, CodexWrench } from "@/icons";
import { cn } from "@/lib/utils";
import { PanelPortal } from "@/shell";
import { SettingsButton, SettingsCard, SettingsCardBody, SettingsRow, SettingsSection, SettingsSwitch } from "@/settings";
import { Input, Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/ui";

/**
 * ARTEX 设置页（rail「设置」，外壳路由 /artex-settings）—— 外壳原生渲染 ARTEX 的真实设置。
 *
 * 数据：`GET /api/settings`（扁平对象，见后端 Settings）；写：`PUT /api/settings`，**只发被改的字段**（后端接受 partial）。
 * 表现层用外壳自己的设置件（SettingsSection / SettingsCard / SettingsRow / SettingsSwitch）+ 复制层无关的 @/ui Select。
 *
 * 诚实原则：
 *  · 每个开关/输入框都直连真实读写，**不做假交互**；
 *  · API key 这类只回 `*_key_set` 布尔的，显示「已配置 / 未配置」，不回显密钥；
 *  · 保存失败如实显示错误，不吞掉。
 */

interface ArtexSettings {
  agent_traffic_binding?: boolean;
  brave_key_set?: boolean;
  constraints_inject_planner?: boolean;
  constraints_inject_worker?: boolean;
  global_proxy?: string;
  llm_pool_bind_fallback?: boolean;
  llm_pool_enabled?: boolean;
  llm_record?: boolean;
  python_interpreter?: string;
  task_concurrency_enabled?: boolean;
  task_concurrency_limit?: number;
  tavily_key_set?: boolean;
  traffic_capture?: boolean;
  web_search_backend?: string;
  web_search_enabled?: boolean;
  web_search_proxy?: string;
  workers?: number;
}

/** 分区导航：与页面里的 <div id="sec-*"> 一一对应；点面板项 = 激活 + 滚到该分区。 */
const SECTIONS = [
  { id: "network", label: "网络与流量", icon: CodexGlobe },
  { id: "search", label: "网络搜索", icon: CodexGearLg },
  { id: "tasks", label: "任务与并发", icon: CodexRailScheduled },
  { id: "runtime", label: "运行时", icon: CodexWrench },
];

const BACKENDS = [
  { value: "ddgs", label: "ddgs（内置）" },
  { value: "tavily", label: "Tavily" },
  { value: "brave", label: "Brave" },
];

export function ArtexSettingsRoute() {
  const { data, error, loading, reload } = useArtexQuery<ArtexSettings>("/api/settings");
  const [draft, setDraft] = useState<ArtexSettings | null>(null);
  const [saving, setSaving] = useState<string | null>(null);
  const [saveError, setSaveError] = useState<string | null>(null);
  const [active, setActive] = useState("network");

  useEffect(() => {
    if (data) setDraft(data);
  }, [data]);

  /** 保存 patch：只发改动字段；成功后用后端返回的整份设置覆盖本地 draft。 */
  async function save(key: string, patch: Partial<ArtexSettings>) {
    setSaving(key);
    setSaveError(null);
    try {
      const next = await artexFetch<ArtexSettings>("/api/settings", { method: "PUT", body: patch });
      setDraft(next);
    } catch (cause) {
      setSaveError(cause instanceof Error ? cause.message : String(cause));
    } finally {
      setSaving(null);
    }
  }

  const value = draft ?? data ?? {};

  function goto(id: string) {
    setActive(id);
    document.getElementById("sec-" + id)?.scrollIntoView({ block: "start", behavior: "smooth" });
  }

  return (
    <div className="cx-page" data-page="artex-settings">
      {/* 面板侧：分区导航。结构与类名对齐外壳自己的设置面板（SidebarPanel.tsx 的 settings-group/list/item），
          不新造类 —— 2026-10-13 修正：此前只用了 settings-item/label 而没有 settings-list 包裹与图标。 */}
      <PanelPortal>
        <div className="codex-panel__settings-group">
          <h2 className="codex-panel__settings-group-title">设置</h2>
          <nav aria-label="设置分区" className="codex-panel__settings-list">
            {SECTIONS.map((section) => {
              const Icon = section.icon;
              const isActive = active === section.id;
              // 官方是 NavLink（SidebarPanel.tsx:440）。这里用 <a href="#sec-…">：
              // 既是真锚点（可键盘/中键），也避开 <button> 的 UA text-align:center。
              return (
                <a
                  aria-current={isActive ? "page" : undefined}
                  className={cn("codex-panel__settings-item", isActive && "is-active")}
                  href={"#sec-" + section.id}
                  key={section.id}
                  onClick={(event) => {
                    event.preventDefault();
                    goto(section.id);
                  }}
                >
                  <span className="codex-panel__settings-item-icon">
                    <Icon aria-hidden size={16} />
                  </span>
                  <span className="codex-panel__settings-item-label">{section.label}</span>
                </a>
              );
            })}
          </nav>
        </div>
      </PanelPortal>

      <div className="cx-page__body">
        {loading ? <span className="cx-muted">正在加载设置</span> : null}

        {!loading && error ? (
          <div className="cx-page__section">
            <h2 className="cx-page__section-title">设置加载失败</h2>
            <p className="cx-muted">
              {"ARTEX API 返回 " + error.status + (error.message ? "：" + error.message : "") +
                (error.status === 401 ? "（令牌可能已失效：回到「对话」页会自动续期）" : "")}
            </p>
            <SettingsButton onClick={reload}>
              重试
            </SettingsButton>
          </div>
        ) : null}

        {!loading && !error ? (
          <>
            {saveError ? (
              <p className="cx-muted">保存失败：{saveError}</p>
            ) : null}

            <div id="sec-network">
            <SettingsSection title="网络与流量">
              <SettingsCard>
                <SettingsCardBody>
                  <SettingsRow
                    control={
                      <SettingsSwitch
                        checked={!!value.traffic_capture}
                        disabled={saving === "traffic_capture"}
                        label="" onChange={(checked: boolean) => save("traffic_capture", { traffic_capture: checked })}
                      />
                    }
                    description="抓取任务过程中的请求/响应，供发现页取证。"
                    label="流量捕获"
                  />
                  <SettingsRow
                    control={
                      <SettingsSwitch
                        checked={!!value.agent_traffic_binding}
                        disabled={saving === "agent_traffic_binding"}
                        label="" onChange={(checked: boolean) => save("agent_traffic_binding", { agent_traffic_binding: checked })}
                      />
                    }
                    description="把 Agent 的请求并入当前任务的流量视图。"
                    label="Agent 流量绑定"
                  />
                  <SettingsRow
                    control={
                      <SettingsSwitch
                        checked={!!value.llm_record}
                        disabled={saving === "llm_record"}
                        label="" onChange={(checked: boolean) => save("llm_record", { llm_record: checked })}
                      />
                    }
                    description="记录每次 LLM 调用，供「LLM 记录」页查看。"
                    label="记录 LLM 调用"
                  />
                  <SettingsRow
                    control={
                      <Input
                        defaultValue={value.global_proxy ?? ""}
                        onBlur={(event) => {
                          const next = event.currentTarget.value.trim();
                          if (next !== (value.global_proxy ?? "")) save("global_proxy", { global_proxy: next });
                        }}
                        placeholder="如 http://127.0.0.1:7890，留空=直连"
                        size="md"
                      />
                    }
                    description="所有出站请求（含 Agent 工具）走这个代理。"
                    label="全局代理"
                  />
                </SettingsCardBody>
              </SettingsCard>
            </SettingsSection>
            </div>

            <div id="sec-search">
            <SettingsSection title="网络搜索">
              <SettingsCard>
                <SettingsCardBody>
                  <SettingsRow
                    control={
                      <SettingsSwitch
                        checked={!!value.web_search_enabled}
                        disabled={saving === "web_search_enabled"}
                        label="" onChange={(checked: boolean) => save("web_search_enabled", { web_search_enabled: checked })}
                      />
                    }
                    description={"允许 Agent 联网检索（后端 = " + (value.web_search_backend || "未设置") + "）。"}
                    label="启用网络搜索"
                  />
                  <SettingsRow
                    control={
                      <Select
                        disabled={saving === "web_search_backend"}
                        onValueChange={(next: string) => save("web_search_backend", { web_search_backend: next })}
                        value={value.web_search_backend || "ddgs"}
                      >
                        <SelectTrigger>
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          {BACKENDS.map((backend) => (
                            <SelectItem key={backend.value} value={backend.value}>
                              {backend.label}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    }
                    description="检索后端；Tavily / Brave 需要在服务端配置 API Key。"
                    label="搜索后端"
                  />
                  <SettingsRow
                    control={
                      <Input
                        defaultValue={value.web_search_proxy ?? ""}
                        onBlur={(event) => {
                          const next = event.currentTarget.value.trim();
                          if (next !== (value.web_search_proxy ?? "")) save("web_search_proxy", { web_search_proxy: next });
                        }}
                        placeholder="可留空"
                        size="md"
                      />
                    }
                    description="仅搜索请求走这个代理（留空则跟随全局）。"
                    label="搜索代理"
                  />
                  <SettingsRow
                    control={<span className="cx-muted">{value.tavily_key_set ? "已配置" : "未配置"}</span>}
                    description="服务端是否已保存 Tavily API Key（不回显密钥本身）。"
                    label="Tavily Key"
                  />
                  <SettingsRow
                    control={<span className="cx-muted">{value.brave_key_set ? "已配置" : "未配置"}</span>}
                    description="服务端是否已保存 Brave API Key（不回显密钥本身）。"
                    label="Brave Key"
                  />
                </SettingsCardBody>
              </SettingsCard>
            </SettingsSection>
            </div>

            <div id="sec-tasks">
            <SettingsSection title="任务与并发">
              <SettingsCard>
                <SettingsCardBody>
                  <SettingsRow
                    control={
                      <SettingsSwitch
                        checked={!!value.constraints_inject_planner}
                        disabled={saving === "constraints_inject_planner"}
                        label="" onChange={(checked: boolean) => save("constraints_inject_planner", { constraints_inject_planner: checked })}
                      />
                    }
                    description="把任务约束注入规划者（planner）的提示词。"
                    label="约束注入 · 规划者"
                  />
                  <SettingsRow
                    control={
                      <SettingsSwitch
                        checked={!!value.constraints_inject_worker}
                        disabled={saving === "constraints_inject_worker"}
                        label="" onChange={(checked: boolean) => save("constraints_inject_worker", { constraints_inject_worker: checked })}
                      />
                    }
                    description="把任务约束注入执行者（worker）的提示词。"
                    label="约束注入 · 执行者"
                  />
                  <SettingsRow
                    control={
                      <SettingsSwitch
                        checked={!!value.task_concurrency_enabled}
                        disabled={saving === "task_concurrency_enabled"}
                        label="" onChange={(checked: boolean) => save("task_concurrency_enabled", { task_concurrency_enabled: checked })}
                      />
                    }
                    description="限制同时运行的任务数（默认 = 5）。"
                    label="限制任务并发"
                  />
                  <SettingsRow
                    control={
                      <Input
                        defaultValue={String(value.task_concurrency_limit ?? 5)}
                        onBlur={(event) => {
                          const next = Number(event.currentTarget.value.trim());
                          if (Number.isFinite(next) && next !== value.task_concurrency_limit) {
                            save("task_concurrency_limit", { task_concurrency_limit: next });
                          }
                        }}
                        size="md"
                        type="number"
                      />
                    }
                    description="并发上限；仅在上面的开关打开时生效。"
                    label="并发上限"
                  />
                  <SettingsRow
                    control={
                      <Input
                        defaultValue={String(value.workers ?? 3)}
                        onBlur={(event) => {
                          const next = Number(event.currentTarget.value.trim());
                          if (Number.isFinite(next) && next !== value.workers) save("workers", { workers: next });
                        }}
                        size="md"
                        type="number"
                      />
                    }
                    description="任务内并行执行的 worker 数。"
                    label="Worker 数"
                  />
                </SettingsCardBody>
              </SettingsCard>
            </SettingsSection>
            </div>

            <div id="sec-runtime">
            <SettingsSection title="运行时">
              <SettingsCard>
                <SettingsCardBody>
                  <SettingsRow
                    control={
                      <Input
                        defaultValue={value.python_interpreter ?? ""}
                        onBlur={(event) => {
                          const next = event.currentTarget.value.trim();
                          if (next !== (value.python_interpreter ?? "")) save("python_interpreter", { python_interpreter: next });
                        }}
                        size="md"
                      />
                    }
                    description="Agent 执行 Python 工具时使用的解释器路径。"
                    label="Python 解释器"
                  />
                  <SettingsRow
                    control={
                      <SettingsSwitch
                        checked={!!value.llm_pool_enabled}
                        disabled={saving === "llm_pool_enabled"}
                        label="" onChange={(checked: boolean) => save("llm_pool_enabled", { llm_pool_enabled: checked })}
                      />
                    }
                    description="在多个 LLM Profile 之间做故障转移。"
                    label="LLM 池"
                  />
                  <SettingsRow
                    control={
                      <SettingsSwitch
                        checked={!!value.llm_pool_bind_fallback}
                        disabled={saving === "llm_pool_bind_fallback"}
                        label="" onChange={(checked: boolean) => save("llm_pool_bind_fallback", { llm_pool_bind_fallback: checked })}
                      />
                    }
                    description="池内全部失败时回退到默认 Profile。"
                    label="LLM 池回退"
                  />
                </SettingsCardBody>
              </SettingsCard>
            </SettingsSection>
            </div>
          </>
        ) : null}
      </div>
    </div>
  );
}