import { Navigate, useParams } from "react-router-dom";

import { ChatRoute as ChatHomeView, ConversationRoute as ConversationView } from "@/chat";
import {
  ArtexChatRoute,
  ArtexSettingsRoute,
  ExploreRoute,
  FindingsRoute,
  IntranetRoute,
  PluginsRoute,
  ReviewRoute,
  ScheduledRoute,
  TasksRoute,
} from "@/pages";
import { SettingsPage } from "@/settings";
import { ControlsGallery } from "@/ui";

/**
 * 路由出口的**唯一接线点**（lead 独占）。
 *
 * 各功能域只从自己的 barrel 导出组件，不直接互相 import；跨域装配集中在这里，
 * 这样任何一个域重构内部结构都不会牵动别人。
 *
 *   /new                  首页态（新聊天）
 *   /c/:conversationId    会话态
 *   /settings/:section    设置页（section 缺省时由 SettingsPage 回落到默认分区）
 */
export const ChatRoute = ChatHomeView;
export const ConversationRoute = ConversationView;

// rail 的其余四项（官方 rail 实测序：首页/定时任务/插件/探索 ── 代码审查）
export const ScheduledRouteView = ScheduledRoute;
export const PluginsRouteView = PluginsRoute;
export const ExploreRouteView = ExploreRoute;
export const ReviewRouteView = ReviewRoute;
// ARTEX 任务页：外壳原生渲染 + 直连 ARTEX API（objective ② 的第一页）
export const TasksRouteView = TasksRoute;
// ARTEX 发现页：外壳原生渲染 + 直连 ARTEX API
export const FindingsRouteView = FindingsRoute;
// ARTEX 内网页：外壳原生渲染（ARTEX 独有业务面，用同一套复制件拼装）
export const IntranetRouteView = IntranetRoute;
// ARTEX 设置页：外壳原生渲染 ARTEX 真实设置（GET/PUT /api/settings）
export const ArtexSettingsRouteView = ArtexSettingsRoute;
// 外壳原生会话态（内测路由，暂未接 rail）：读 + 发的最小闭环
export const ArtexChatRouteView = ArtexChatRoute;

/** 设置页自带分区导航，section 由它自己从 useParams 读取 */
export function SettingsRoute() {
  return <SettingsPage />;
}

export function SettingsSectionRoute() {
  return <SettingsPage />;
}

/** 控件库（/controls）：本工程已还原控件的标本台页面（task-38 用户需求） */
export function ControlsRoute() {
  return <ControlsGallery />;
}

/**
 * 宿主容器（/artex）：把本地 ARTEX 控制台当作内容主体托进外壳。
 * 它不是官方路由 —— 是本工程作为「宿主」的扩展点，落在 src/shell/host/ 里，
 * 与官方路由零耦合（不改 rail、不改官方页面档位，verify 的 12 条几何断言不受影响）。
 */
export { ArtexHostPage as ArtexHostRoute } from "./host/ArtexHostPage";

/** 未知路径回落到首页（新聊天），而不是给一个死页面 */
export function NotFoundRoute() {
  return <Navigate replace to="/new" />;
}

/** 供需要读会话 id 的组件复用 */
export function useConversationId() {
  return useParams().conversationId;
}
