import { StrictMode } from "react";
import { createRoot } from "react-dom/client";

import { App } from "./App";
import "./styles/index.css";

// 根元素上打官方同款窗口类型标记：官方对 Electron 窗口另有一档 token
document.documentElement.setAttribute("data-codex-window-type", "electron");
document.documentElement.setAttribute("data-codex-os", "win32");
document.documentElement.lang = "zh-CN";

const container = document.getElementById("root");
if (!container) throw new Error("index.html 缺少 #root 容器");

createRoot(container).render(
  <StrictMode>
    <App />
  </StrictMode>,
);

// 官方启动方式：React 首帧后把 index.html 里的启动 loader 淡出。
// loader 本体（OpenAI 花标 + shimmer 动画）在 index.html 的内联 <style> 与 DOM 里，
// 与发行版逐字节一致，见 docs/startup-loader.css。
requestAnimationFrame(() => {
  const loader = document.querySelector<HTMLElement>(".startup-loader");
  if (!loader) return;
  loader.dataset.dismissed = "true";
  window.setTimeout(() => loader.setAttribute("hidden", ""), 220);
});
