import { useMemo, useState } from "react";

import { useArtexQuery } from "@/api/artex";
import { PanelPortal } from "@/shell";
import { CodexRailReview, CodexRefresh, CodexSearch, CodexX } from "@/icons";
import { Button } from "@/ui";

import { EmptyState, RowSkeleton } from "./parts";

/**
 * 发现页（rail「发现」，外壳路由 /findings）—— objective ② 的第二个「外壳原生渲染」页面。
 *
 * 与 /tasks 同一套路：外壳自己的组件与样式画页面，数据走 src/api/artex.ts 直连 ARTEX API
 * （/api/exploration/findings，契约见控制台 src/lib/types.ts:Finding）。
 * token 由静默宿主容器提供（HostAuthFrame），后端 CORS 已放行 Authorization。
 *
 * 只取本页用到的字段；未知严重度/状态原样显示，不猜。
 */

interface ArtexFinding {
  id: string;
  finding_id?: string;
  vulnclass?: string;
  name?: string;
  severity?: string;
  status?: string;
  summary?: string;
  task_id?: string;
  task_description?: string;
  ts?: string;
  assets?: unknown[];
}

const SEVERITY_LABEL: Record<string, string> = {
  critical: "严重",
  high: "高危",
  medium: "中危",
  low: "低危",
  info: "提示",
};

const STATUS_LABEL: Record<string, string> = {
  open: "待处理",
  confirmed: "已确认",
  fixed: "已修复",
  false_positive: "误报",
  ignored: "已忽略",
};

function severityText(finding: ArtexFinding): string {
  const raw = (finding.severity ?? "").trim();
  if (!raw) return "未分级";
  return SEVERITY_LABEL[raw] ?? raw;
}

function severityTone(finding: ArtexFinding): string | undefined {
  const raw = (finding.severity ?? "").trim();
  if (raw === "critical" || raw === "high") return "danger";
  if (raw === "low" || raw === "info") return "muted";
  return undefined;
}

function statusText(finding: ArtexFinding): string {
  const raw = (finding.status ?? "").trim();
  if (!raw) return "未知";
  return STATUS_LABEL[raw] ?? raw;
}

function findingTitle(finding: ArtexFinding): string {
  const named = (finding.name ?? "").trim();
  if (named) return named;
  const cls = (finding.vulnclass ?? "").trim();
  if (cls) return cls;
  const summary = (finding.summary ?? "").trim();
  if (summary) return summary.length > 80 ? summary.slice(0, 80) + "…" : summary;
  return "未命名发现";
}

function findingMeta(finding: ArtexFinding): string {
  const parts: string[] = [];
  const task = (finding.task_description ?? "").trim();
  if (task) parts.push(task.length > 40 ? task.slice(0, 40) + "…" : task);
  if (Array.isArray(finding.assets) && finding.assets.length > 0) parts.push(finding.assets.length + " 个资产");
  if (finding.ts && finding.ts.trim()) parts.push(finding.ts.trim());
  return parts.join(" · ");
}

export function FindingsRoute() {
  const { data, error, loading, reload } = useArtexQuery<ArtexFinding[]>("/api/exploration/findings");
  const [query, setQuery] = useState("");
  /** 选中项（官方：面板行选中 ⇒ 主面出详情）。 */
  const [selectedId, setSelectedId] = useState<string | null>(null);

  const findings = Array.isArray(data) ? data : [];
  const filtered = useMemo(() => {
    const needle = query.trim().toLowerCase();
    if (!needle) return findings;
    return findings.filter((finding) => {
      const haystack = [findingTitle(finding), finding.summary ?? "", finding.vulnclass ?? "", severityText(finding)]
        .join(" ")
        .toLowerCase();
      return haystack.includes(needle);
    });
  }, [findings, query]);

  const selected = filtered.find((finding) => finding.id === selectedId) ?? null;
  const critical = findings.filter((finding) => severityText(finding) === "严重" || severityText(finding) === "高危").length;

  return (
    <div className="cx-page" data-page="findings">
      <div className="cx-split" data-panel-layout="panel">
        <PanelPortal>
          <div className="codex-panel__page-section">
            <div className="codex-panel__page-section-title">
              <div className="codex-panel__page-section-label">发现</div>
              <button aria-label="刷新发现" className="codex-panel__icon-button" onClick={reload} type="button">
                <CodexRefresh size={16} />
              </button>
            </div>
            <div className="codex-panel__page-search">
              <CodexSearch size={16} />
              <input
                aria-label="搜索发现"
                className="codex-panel__page-search-input"
                onChange={(event) => setQuery(event.target.value)}
                placeholder="搜索发现"
                type="text"
                value={query}
              />
              {query ? (
                <button aria-label="清空搜索" className="codex-panel__page-search-clear" onClick={() => setQuery("")} type="button">
                  <CodexX size={14} />
                </button>
              ) : null}
            </div>
            {loading ? <RowSkeleton rows={3} /> : null}
            <div className="codex-panel__page-list">
              {!loading && error ? (
                <div className="codex-panel__page-empty-row" role="status">发现加载失败</div>
              ) : null}
              {!loading && !error && filtered.length === 0 ? (
                <div className="codex-panel__page-empty-row" role="status">
                  {query ? "没有匹配的发现" : "暂无发现"}
                </div>
              ) : null}
              {!loading && !error
                ? filtered.map((finding) => (
                    <div className="codex-panel__page-row-wrap" key={finding.id}>
                      <button
                        aria-pressed={finding.id === selectedId}
                        className="codex-panel__page-row"
                        data-selected={finding.id === selectedId ? "true" : undefined}
                        onClick={() => setSelectedId(finding.id)}
                        type="button"
                      >
                        <span className="codex-panel__page-row-title">{findingTitle(finding)}</span>
                        <span className="codex-panel__page-row-plan">
                          {severityText(finding)} · {statusText(finding)}
                          {findingMeta(finding) ? " · " + findingMeta(finding) : ""}
                        </span>
                      </button>
                    </div>
                  ))
                : null}
            </div>
          </div>
        </PanelPortal>

        <aside className="cx-split__detail">
          {selected ? (
            <>
              <header className="cx-detail__header">
                <span className="cx-detail__title">{findingTitle(selected)}</span>
              </header>
              <div className="cx-detail__scroll">
                <div className="cx-detail__field">
                  <span className="cx-detail__label">严重度</span>
                  <span className="cx-detail__value">{severityText(selected)}</span>
                </div>
                <div className="cx-detail__field">
                  <span className="cx-detail__label">状态</span>
                  <span className="cx-detail__value">{statusText(selected)}</span>
                </div>
                <section className="cx-detail__field">
                  <span className="cx-detail__label">摘要</span>
                  <span className="cx-detail__value">{(selected.summary ?? "").trim() || "—"}</span>
                </section>
              </div>
            </>
          ) : (
            <EmptyState
              actions={
                error ? (
                  <Button onClick={reload} size="sm" variant="surface">重试</Button>
                ) : undefined
              }
              description={
                error
                  ? "ARTEX API 返回 " + error.status + (error.message ? "：" + error.message : "")
                  : query
                    ? "没有符合「" + query + "」的发现。"
                    : "左侧选中一个发现查看详情。"
              }
              icon={CodexRailReview}
              layout="page"
              title={error ? "发现加载失败" : "发现"}
              titleAs="h1"
            />
          )}
        </aside>
      </div>
    </div>
  );
}
