import { useSyncExternalStore } from "react";

import { Popover } from "radix-ui";
import { NavLink, useLocation, useNavigate } from "react-router-dom";

import { cn } from "@/lib/utils";
import {
  getHostGuest,
  guestRouteMatches,
  navigateGuest,
  requestGuestPath,
  subscribeHostGuest,
} from "./host/host-store";
import {
  RAIL_BOTTOM_ITEMS,
  RAIL_EXPLORE_MENU,
  RAIL_HOST_BOTTOM_ITEMS,
  RAIL_HOST_ITEMS,
  RAIL_PRIMARY_ITEMS,
  RAIL_SECONDARY_ITEMS,
  type HostRailItem,
  type RailItem,
} from "./rail-items";

/**
 * 52px 图标导轨（官方 `nav.group/sidebar-rail`）。
 *
 * ── 几何（官方 capture 实测，captures/tree-rail.json + blocks-sidebar.json）──
 *   nav            [0,44 **52**×768]  padding-top calc((52-36)/2)=8  padding-bottom 4
 *   nav-list       [6,50 **40**×716]  margin -2px / padding 2px / gap 8px
 *   按钮           [8,52/96/140/184/236.67 **36×36**]  图标 20×20 居中
 *                  radius **12.5px**  corner-shape **superellipse(1.5)**
 *   分隔线         [14,228 **24×0.67**]
 *   底部组         [8,772 36×36]
 *
 * ── 元素形态：官方是 `button`，**不是** `<a>`（task-25 收口的真差异）──────
 * 原始取证 captures/tree-rail.json（同一份 DOM 树的属性转储）：
 * ```
 *   tag: "button"                                        ← 没有也不可能带 href
 *   cls: "_Button_eg66f_2 browser:[--button-text-color:var(--color-text-tertiary)]
 *         browser:data-selected:[--button-text-color:var(--color-text-primary-ghost)] …"
 *   dataAttrs: { data-color: "secondary", data-variant: "ghost", data-squircle: "",
 *                data-uniform: "", data-size: "xl", data-icon-size: "lg",
 *                data-sidebar-destination: "builtin:home",        // 首页
 *                data-slate-sidebar-peek-area: "home",
 *                data-state: "closed", data-selected: "" }        // ← 选中态
 *   可访问名：**来自内部 sr-only 文本**（capture 的 aria 字段 = null 的 5 条都带 text「首页/定时任务/插件/探索/代码审查」）
 *   底部那条是例外：aria-label="打开个人资料菜单"（没有可见/隐藏文本），且带 id="radix-_r_17_"（popover 触发钮）
 * ```
 * `tree-rail.json` 整棵树里**没有任何 `aria-*` 属性**（grep 只匹配到 data-variant），
 * 即官方**没有** `aria-current`；选中态只由 `data-selected` 表达。
 *
 * 本工程的做法：**形态对齐官方**（`button` + `onClick` 路由），
 * 同时**额外保留** `aria-current="page"` 与 `aria-label`（官方用 sr-only 文本给可访问名，
 * 我们这条口径等价、更省一层 DOM）；另加官方的 `data-selected` 便于逐条对照。
 *
 * ⚠️ 契约变更（有意，非回归）：去掉真实 `href` 后，**中键新开 / 右键「在新标签页打开」不再可用**，
 * 这是官方行为（官方那条根本没有链接语义）。键盘可达性不受影响：`<button>` 可 Tab 聚焦、
 * Enter/Space 都会激活，与官方一致。
 */

/** NavLink 默认匹配语义（`end=false`）：路径完全相等，或落在它的子路径上 */
function isRailItemActive(pathname: string, to: string) {
  return pathname === to || pathname.startsWith(to.endsWith("/") ? to : `${to}/`);
}

function RailButton({ className, item }: { className?: string; item: RailItem }) {
  const { pathname } = useLocation();
  const navigate = useNavigate();
  const Icon = item.icon;
  const IconActive = item.iconActive;
  // [task-40] `RailItem.to` 现在是可选的（「探索」是菜单、没有目的地）⇒
  // 没有目的地的条目不该被当作跳转按钮渲染（RailExplore 走的是另一条分支）。
  const to = item.to;
  if (!to) return null;
  const active = isRailItemActive(pathname, to);
  const Glyph = active && IconActive ? IconActive : Icon;
  return (
    <button
      aria-current={active ? "page" : undefined}
      aria-label={item.label}
      className={cn("codex-rail__item", active && "is-active", className)}
      data-rail-id={item.id}
      data-selected={active ? "" : undefined}
      onClick={() => navigate(to)}
      type="button"
    >
      <Glyph size={20} />
    </button>
  );
}

/**
 * 「探索」轨条：**不跳转**，开一个 popover 菜单（官方 `renderExploreMenu`）。
 * 选中态 = 当前路由命中菜单里的任一条目。
 * 官方这条的 `data-slot="popover-trigger"`（captures/tree-rail.json 实测）在这里照抄。
 */
function RailExplore({ item }: { item: RailItem }) {
  const { pathname } = useLocation();
  const Icon = item.icon;
  const active = RAIL_EXPLORE_MENU.some((entry) => pathname === entry.to);
  return (
    <Popover.Root>
      <Popover.Trigger asChild>
        <button
          aria-label={item.label}
          className={cn("codex-rail__item", active && "is-active")}
          data-rail-id={item.id}
          data-selected={active ? "" : undefined}
          data-slot="popover-trigger"
          type="button"
        >
          <Icon size={20} />
        </button>
      </Popover.Trigger>
      <Popover.Portal>
        <Popover.Content
          align="start"
          className="codex-app-menu codex-rail__menu"
          data-codex-rail-menu=""
          side="right"
          sideOffset={8}
        >
          {RAIL_EXPLORE_MENU.map((entry) => {
            const EntryIcon = entry.icon;
            // 浮层条目仍是 NavLink：官方 exploreDestinations 是账号门控清单、本机未渲染出菜单，
            // 条目形态**未实测**；保留真实 href 让「菜单里挂死条目」这类缺陷仍可被断言抓到。
            return (
              <NavLink
                className="codex-app-menu__item"
                data-rail-menu-id={entry.id}
                key={entry.id}
                to={entry.to}
              >
                <EntryIcon aria-hidden size={16} />
                <span className="codex-app-menu__label">{entry.label}</span>
              </NavLink>
            );
          })}
        </Popover.Content>
      </Popover.Portal>
    </Popover.Root>
  );
}


/**
 * ARTEX 应用路由判据：只要是「ARTEX 应用」的页面，导轨就该显示 ARTEX 的目的地
 * （对话 / 任务 / 发现 / 内网 / 设置），而不是壳自己的 Codex 条目。
 *
 * 为什么不能只看 /artex：迁移期里 /tasks、/findings 这些页面已经由外壳原生渲染
 * （objective ②），用户在这三页之间切换时导轨不该变脸。
 */
const ARTEX_ROUTES = ["/artex", "/tasks", "/findings", "/intranet", "/artex-settings", "/artex-chat"];

export function isHostRoute(pathname: string) {
  return ARTEX_ROUTES.some((route) => pathname === route || pathname.startsWith(route + "/"));
}

/**
 * 托管态的单条导轨按钮。
 *
 * 与 RailButton 的差别只有「目的地在哪」：官方条目跳外壳自己的路由（navigate(to)），
 * 托管条目跳**访客应用内**的路由（navigateGuest(path)，见 host-store）。
 * 选中态读访客上报的路由：外壳路由恒为 /artex，拿它比对不会有任何一条点亮。
 */
function HostRailButton({ item }: { item: HostRailItem }) {
  const guest = useSyncExternalStore(subscribeHostGuest, getHostGuest);
  const navigate = useNavigate();
  const { pathname } = useLocation();
  const Icon = item.icon;
  const IconActive = item.iconActive;
  // 选中态：shell 档看外壳路由；guest 档看访客上报的路由。
  const active =
    item.kind === "shell" ? isRailItemActive(pathname, item.path) : guestRouteMatches(guest.route, item.path);
  /**
   * 迁移期两种点击：
   *  · shell 档：该页已由外壳原生渲染 ⇒ 直接跳外壳路由（iframe 不在这一页）。
   *  · guest 档：该页仍是控制台在画 ⇒ 先记下访客路径再切到 /artex（HostFrame ready 后补发），
   *    避免「在外壳其它页面上点一下没反应」。
   */
  const go = () => {
    if (item.kind === "shell") {
      navigate(item.path);
      return;
    }
    requestGuestPath(item.path);
    navigate("/artex");
  };
  const Glyph = active && IconActive ? IconActive : Icon;
  return (
    <button
      aria-current={active ? "page" : undefined}
      aria-label={item.label}
      className={cn("codex-rail__item", active && "is-active")}
      data-host-path={item.path}
      data-rail-id={item.id}
      data-selected={active ? "" : undefined}
      onClick={item.kind === "guest" && pathname === "/artex" ? () => navigateGuest(item.path) : go}
      title={item.label}
      type="button"
    >
      <Glyph size={20} />
    </button>
  );
}
export function SidebarRail({ className }: { className?: string }) {
  const { pathname } = useLocation();
  const hostRoute = isHostRoute(pathname);

  // 托管态（/artex）：导轨换成 ARTEX 的目的地，点击驱动 iframe 里的访客路由。
  // 官方五条（首页/定时任务/插件/探索/代码审查）在本档下没有对应的访客页面，
  // 留着会变成「点了跳到外壳的样例页」的死入口（2026-10-13 决定）。
  if (hostRoute) {
    return (
      <nav
        aria-label="主导航"
        className={cn("codex-rail", className)}
        data-app-navigation-rail="true"
        data-host-rail="true"
      >
        <div className="codex-rail__list">
          {RAIL_HOST_ITEMS.map((item) => (
            <HostRailButton item={item} key={item.id} />
          ))}
        </div>
        <div className="codex-rail__bottom">
          {RAIL_HOST_BOTTOM_ITEMS.map((item) => (
            <HostRailButton item={item} key={item.id} />
          ))}
        </div>
      </nav>
    );
  }

  return (
    <nav aria-label="主导航" className={cn("codex-rail", className)} data-app-navigation-rail="true">
      <div className="codex-rail__list">
        {RAIL_PRIMARY_ITEMS.map((item) =>
          item.menu ? <RailExplore item={item} key={item.id} /> : <RailButton item={item} key={item.id} />,
        )}
        <div aria-hidden className="codex-rail__divider" />
        {RAIL_SECONDARY_ITEMS.map((item) => (
          <RailButton item={item} key={item.id} />
        ))}
      </div>

      <div className="codex-rail__bottom">
        {RAIL_BOTTOM_ITEMS.map((item) => (
          // [task-55] 去掉死类名 codex-rail__item--bottom：CSS 从无该规则；底部槽布局由父级
          // .codex-rail__bottom、条目几何由 RailButton 自带的 .codex-rail__item 承担。
          <RailButton item={item} key={item.id} />
        ))}
      </div>
    </nav>
  );
}