import { useMemo, useState } from "react";

import { useArtexQuery } from "@/api/artex";
import { CodexRefresh, CodexTranslate } from "@/icons";
import { PanelPortal } from "@/shell";
import { Button } from "@/ui";

import { EmptyState, RowSkeleton } from "./parts";

/**
 * 内网页（rail「内网」，外壳路由 /intranet）—— objective ② 的第三个「外壳原生渲染」页面。
 *
 * 口径（objective ③ 的登记）：内网是 **ARTEX 独有业务面**，官方 Codex 没有对应页面，
 * 所以这一页不承诺 1:1；承诺的是「用同一套复制件与 token 拼装」——组件、字号、行高都来自官方件。
 *
 * 数据：/api/sessions（webshell 会话）与 /api/intranet/tunnels（隧道）。响应可能是数组，
 * 也可能是 { sessions } / { tunnels } 包装 —— 两种都收，取不到就如实显示空态。
 */

interface ShellSession {
  id: string;
  kind?: string;
  url?: string;
  lang?: string;
  platform?: string;
  host_asset_id?: string;
  status?: string;
  last_beat?: string;
}

interface TunnelInfo {
  id: string;
  kind?: string;
  state?: string;
  listen_host?: string;
  listen_port?: number;
  target_host?: string;
  target_port?: number;
  last_check?: string;
  error?: string;
}

/** 列表响应兼容三种形态：数组 / { items } / { <key>: [] }。 */
function toList<T>(value: unknown, key: string): T[] {
  if (Array.isArray(value)) return value as T[];
  if (value && typeof value === "object") {
    const record = value as Record<string, unknown>;
    if (Array.isArray(record[key])) return record[key] as T[];
    if (Array.isArray(record.items)) return record.items as T[];
  }
  return [];
}

export function IntranetRoute() {
  const sessionsQuery = useArtexQuery<unknown>("/api/sessions");
  const tunnelsQuery = useArtexQuery<unknown>("/api/tunnels");

  const sessions = useMemo(() => toList<ShellSession>(sessionsQuery.data, "sessions"), [sessionsQuery.data]);
  const tunnels = useMemo(() => toList<TunnelInfo>(tunnelsQuery.data, "tunnels"), [tunnelsQuery.data]);

  const loading = sessionsQuery.loading || tunnelsQuery.loading;
  const error = sessionsQuery.error ?? tunnelsQuery.error;
  const alive = sessions.filter((session) => (session.status ?? "") === "alive").length;
  const [selected, setSelected] = useState<{ kind: "session" | "tunnel"; id: string } | null>(null);
  const selectedSession = selected?.kind === "session" ? (sessions.find((s) => String(s.id) === selected.id) ?? null) : null;
  const selectedTunnel = selected?.kind === "tunnel" ? (tunnels.find((x) => String(x.id) === selected.id) ?? null) : null;

  return (
    <div className="cx-page" data-page="intranet">
      <div className="cx-split" data-panel-layout="panel">
        <PanelPortal>
          {loading ? (
            <div className="codex-panel__page-section">
              <div className="codex-panel__page-section-title">
                <div className="codex-panel__page-section-label">内网</div>
              </div>
              <RowSkeleton rows={3} />
            </div>
          ) : (
            <>
              <div className="codex-panel__page-section">
                <div className="codex-panel__page-section-title">
                  <div className="codex-panel__page-section-label">会话 {sessions.length}</div>
                  <button aria-label="刷新内网数据" className="codex-panel__icon-button" onClick={() => { sessionsQuery.reload(); tunnelsQuery.reload(); }} type="button">
                    <CodexRefresh size={16} />
                  </button>
                </div>
                <div className="codex-panel__page-list">
                  {sessions.length === 0 ? (
                    <div className="codex-panel__page-empty-row" role="status">暂无会话</div>
                  ) : (
                    sessions.map((item) => (
                      <div className="codex-panel__page-row-wrap" key={"s:" + item.id}>
                        <button
                          aria-pressed={selected?.kind === "session" && selected.id === String(item.id)}
                          className="codex-panel__page-row"
                          data-selected={selected?.kind === "session" && selected.id === String(item.id) ? "true" : undefined}
                          onClick={() => setSelected({ kind: "session", id: String(item.id) })}
                          type="button"
                        >
                          <span className="codex-panel__page-row-title">{item.url || item.host_asset_id || item.id}</span>
                          <span className="codex-panel__page-row-plan">{item.status === "alive" ? "在线" : item.status || "未知"}</span>
                        </button>
                      </div>
                    ))
                  )}
                </div>
              </div>

              <div className="codex-panel__page-section">
                <div className="codex-panel__page-section-title">
                  <div className="codex-panel__page-section-label">隧道 {tunnels.length}</div>
                </div>
                <div className="codex-panel__page-list">
                  {tunnels.length === 0 ? (
                    <div className="codex-panel__page-empty-row" role="status">暂无隧道</div>
                  ) : (
                    tunnels.map((entry) => (
                      <div className="codex-panel__page-row-wrap" key={"t:" + entry.id}>
                        <button
                          aria-pressed={selected?.kind === "tunnel" && selected.id === String(entry.id)}
                          className="codex-panel__page-row"
                          data-selected={selected?.kind === "tunnel" && selected.id === String(entry.id) ? "true" : undefined}
                          onClick={() => setSelected({ kind: "tunnel", id: String(entry.id) })}
                          type="button"
                        >
                          <span className="codex-panel__page-row-title">
                            {(entry.listen_host || "0.0.0.0") + ":" + (entry.listen_port ?? "")}
                            {entry.target_host ? " → " + entry.target_host + (entry.target_port ? ":" + entry.target_port : "") : ""}
                          </span>
                          <span className="codex-panel__page-row-plan">{entry.state === "error" ? "错误" : entry.state || "未知"}</span>
                        </button>
                      </div>
                    ))
                  )}
                </div>
              </div>
            </>
          )}
        </PanelPortal>

        <aside className="cx-split__detail">
          {selectedSession || selectedTunnel ? (
            <>
              <header className="cx-detail__header">
                <span className="cx-detail__title">
                  {selectedSession
                    ? selectedSession.url || selectedSession.host_asset_id || selectedSession.id
                    : (selectedTunnel?.listen_host || "0.0.0.0") + ":" + (selectedTunnel?.listen_port ?? "")}
                </span>
              </header>
              <div className="cx-detail__scroll">
                {selectedSession ? (
                  <>
                    <div className="cx-detail__field"><span className="cx-detail__label">状态</span><span className="cx-detail__value">{selectedSession.status === "alive" ? "在线" : selectedSession.status || "未知"}</span></div>
                    <div className="cx-detail__field"><span className="cx-detail__label">类型</span><span className="cx-detail__value">{selectedSession.kind || "—"}</span></div>
                    <div className="cx-detail__field"><span className="cx-detail__label">平台</span><span className="cx-detail__value">{selectedSession.platform || "—"}</span></div>
                  </>
                ) : (
                  <>
                    <div className="cx-detail__field"><span className="cx-detail__label">状态</span><span className="cx-detail__value">{selectedTunnel?.state || "未知"}</span></div>
                    <div className="cx-detail__field"><span className="cx-detail__label">目标</span><span className="cx-detail__value">{(selectedTunnel?.target_host || "—") + (selectedTunnel?.target_port ? ":" + selectedTunnel.target_port : "")}</span></div>
                  </>
                )}
              </div>
            </>
          ) : (
            <EmptyState
              description={
                error
                  ? "ARTEX API 返回 " + error.status + (error.message ? "：" + error.message : "")
                  : "左侧选中一个会话或隧道查看详情。内网是 ARTEX 独有业务面，用同一套复制件拼装（不承诺 1:1）。"
              }
              icon={CodexTranslate}
              layout="page"
              title={error ? "内网数据加载失败" : "内网"}
              titleAs="h1"
            />
          )}
        </aside>
      </div>
    </div>
  );
}
