/**
 * 宿主容器：把 guest 应用当作内容主体托进外壳。
 *
 * 加载方式：**iframe**。三条理由（都是被本项目既往踩坑逼出来的）：
 *   1. guest 是独立技术栈（Next.js）的本地应用，iframe 是唯一不需要它改代码就能装进来的边界；
 *   2. 与 Electron 解耦 —— 同一份宿主在浏览器 dev 态与 Electron 里行为一致，验证台不需要装桌面端；
 *   3. guest 崩了只是这一帧白，不会把外壳的 React 树一起带走（进程内渲染做不到这点）。
 *
 * 生命周期（四态）：
 *   loading      iframe 已挂载，等 guest 的 `codex-host:ready`
 *   ready        guest 握手完成（此后 route/title 由 guest 主动上报）
 *   unreachable  超过 HOST_READY_TIMEOUT_MS 没握手（guest 没起来/地址不对/被 CSP 拦）
 *   （未配置态在页面层，不在本组件）
 *
 * 主题：外壳的 `mode/resolved` 变了就推 `codex-host:theme`；guest 也可以反向 `theme-request`
 * （它可能在宿主发首帧之后才挂好监听，所以「拉」这一路必须有）。
 */
import { useCallback, useEffect, useRef, useState } from "react";

import { useTheme } from "@/app/theme-provider";

import { createHostBridge, type HostBridge } from "./host-bridge";
import { HOST_READY_TIMEOUT_MS, type HostTarget } from "./host-config";
import {
  resetHostGuest,
  setHostApiOrigin,
  setHostGuest,
  setHostNavigator,
  setHostPanelSender,
  setHostToken,
  takePendingGuestPath,
} from "./host-store";
import "./host.css";

type HostPhase = "loading" | "ready" | "unreachable";

interface GuestInfo {
  route?: string;
  title?: string;
  version?: string;
}

/**
 * `silent` 档：外壳原生页面（/tasks 等）也需要控制台活着提供 access token，
 * 但不需要把控制台画出来 —— 于是把一个 1×1、移出视口的同款容器挂在旁边，
 * 通道与生命周期完全一样（token / 主题 / 路由上报照常），只有视觉不存在。
 * 不用 `display:none`：那会让 Chromium 节流 iframe 的定时器与消息处理。
 */
export function HostFrame({
  target,
  title = "ARTEX",
  silent = false,
  collapseGuestPanel = false,
}: {
  target: HostTarget;
  title?: string;
  silent?: boolean;
  /** 外壳自己画面板时置 true：握手后让访客收起它的面板（见 HostBridge.collapsePanel）。 */
  collapseGuestPanel?: boolean;
}) {
  const frameRef = useRef<HTMLIFrameElement | null>(null);
  const bridgeRef = useRef<HostBridge | null>(null);
  const [phase, setPhase] = useState<HostPhase>("loading");
  const [guest, setGuest] = useState<GuestInfo>({});
  const [notice, setNotice] = useState<string | null>(null);
  const [attempt, setAttempt] = useState(0);
  const timerRef = useRef<number | null>(null);
  // 桥的 message 处理器只建一次（见下），而「让访客跳路由」这条通道要读当前阶段 ——
  // 用 ref 读，避免把 phase 塞进 effect 依赖后重建整条通道。
  const phaseRef = useRef<HostPhase>(phase);
  useEffect(() => {
    phaseRef.current = phase;
  }, [phase]);
  const { mode, resolved } = useTheme();
  // 认证态只暴露「有/无 token」这一位，用于验收（真实 token 不外显）。
  const [guestAuth, setGuestAuth] = useState<"none" | "ready">("none");
  const [tokenProbe, setTokenProbe] = useState({ len: 0, count: 0 });

  /** 重新起算握手超时（重试时也要调，否则重试完还是按旧时钟翻成「未连接」）。 */
  const armTimeout = useCallback(() => {
    if (timerRef.current != null) window.clearTimeout(timerRef.current);
    timerRef.current = window.setTimeout(() => {
      setPhase((current) => (current === "loading" ? "unreachable" : current));
    }, HOST_READY_TIMEOUT_MS);
  }, []);

  // 处理器通过 ref 读主题：桥只建一次，换主题不重建监听（重建会漏掉切换瞬间的消息）。
  const themeRef = useRef({ mode: String(mode), resolved });
  useEffect(() => {
    themeRef.current = { mode: String(mode), resolved };
  }, [mode, resolved]);

  // 桥只建一次（惰性初始化）：它持有 message 监听与 guest origin，重建会漏消息。
  // guest 地址变化由页面层用 key 重挂载整棵组件树来兜底（比在这里静默换 origin 更可预测）。
  const [bridge] = useState(() =>
    createHostBridge({
      getFrame: () => frameRef.current,
      guestOrigin: target.origin,
      handlers: {
        onReady: (payload) => {
          setGuest({ route: payload.route, title: payload.title, version: payload.version });
          // 访客上报的路由/标题同时写进 host-store：外壳的导轨（AppShell 的兄弟节点）
          // 靠它点亮选中态，也靠它把点击送回访客（见下面的导航通道注册）。
          setHostGuest({ route: payload.route, title: payload.title });
          setPhase("ready");
        },
        onRoute: (payload) => {
          setGuest((current) => ({ ...current, route: payload.path, title: payload.title }));
          setHostGuest({ route: payload.path, title: payload.title });
        },
        onThemeRequest: () => bridgeRef.current?.sendInit(themeRef.current),
        // 访客交来的 access token：外壳据此直连 ARTEX API 渲染原生页面（见 src/api/artex.ts）。
        onToken: (payload) => {
          const token = payload.token ?? "";
          setHostToken(token);
          setGuestAuth(token.length > 0 ? "ready" : "none");
          // 诊断位：token 长度 + 收到的 token 消息数（验收用，不暴露令牌本体）。
          setTokenProbe((prev) => ({ len: token.length, count: prev.count + 1 }));
        },
        onNotify: (payload) => setNotice(payload.message),
        onError: (payload) =>
          setNotice(payload.source == null ? payload.message : `${payload.message}（${payload.source}）`),
      },
    }),
  );

  useEffect(() => {
    bridgeRef.current = bridge;
    return () => {
      bridgeRef.current = null;
      bridge.dispose();
    };
  }, [bridge]);

  /**
   * 把「让访客跳路由」的通道登记到 host-store，供外壳的导轨调用
   * （SidebarRail 与 HostFrame 不在同一棵子树里，见 host-store.ts 头注释）。
   * 通道生命周期与桥一致：卸载时一并撤销，避免导轨对着一个已销毁的 iframe 发消息。
   */
  useEffect(() => {
    // 容器挂载即登记 API origin（访客 origin）：外壳直连 ARTEX API 的基址。
    setHostApiOrigin(target.origin);
    setHostNavigator((path) => {
      if (phaseRef.current !== "ready") return false;
      bridge.navigate(path);
      return true;
    });
    // 同一条通道上的第二个动作：菜单栏的「显示/隐藏侧边栏」要作用到访客的面板
    // （托管档下面板归访客画，外壳自己的 useSidebar 在那一档没有可见效果）。
    setHostPanelSender(() => {
      if (phaseRef.current !== "ready") return false;
      return bridge.send("codex-host:panel", { toggle: true });
    });
    return () => {
      setHostNavigator(null);
      setHostPanelSender(null);
      resetHostGuest();
    };
  }, [bridge, target.origin]);

  // 握手超时：只在 loading 阶段计时。
  // 计时器单独持在 ref 里，是为了让 `retry()` 能**显式重新计时** —— 若把 attempt 当 effect 依赖，
  // 依赖表就掺进了「不是本 effect 读的东西」，而且重试发生在 loading 态时不改变 phase、计时不会重来。
  useEffect(() => {
    if (phase !== "loading") return;
    armTimeout();
    return () => {
      if (timerRef.current != null) {
        window.clearTimeout(timerRef.current);
        timerRef.current = null;
      }
    };
  }, [phase, armTimeout]);

  // 迁移期：rail 上未迁移的条目会先记一条「待发送的访客路径」再切到 /artex，
  // 握手完成后在这里补发，避免用户点了没反应（见 host-store 的 requestGuestPath）。
  useEffect(() => {
    if (phase !== "ready") return;
    const pending = takePendingGuestPath();
    if (pending != null) bridge.navigate(pending);
    // 混合档：外壳画 288px 面板 ⇒ 让访客收起它自己的面板（幂等，重复发也无害）。
    if (collapseGuestPanel) bridge.collapsePanel();
  }, [bridge, phase, collapseGuestPanel]);

  // 主题下发：已握手后跟随外壳主题；未握手时不发（首帧由 onLoad 的 init 负责）。
  useEffect(() => {
    if (phase === "loading") return;
    bridge.send("codex-host:theme", { mode: String(mode), resolved });
  }, [bridge, mode, resolved, phase]);

  const handleLoad = useCallback(() => {
    bridge.sendInit(themeRef.current);
  }, [bridge]);

  const retry = useCallback(() => {
    setNotice(null);
    setGuest({});
    setPhase("loading");
    setAttempt((n) => n + 1);
    armTimeout();
  }, [armTimeout]);

  return (
    <div
      className={silent ? "codex-host codex-host--silent" : "codex-host"}
      data-codex-host-guest-route={guest.route ?? ""}
      data-codex-host-guest-title={guest.title ?? ""}
      data-codex-host-auth={guestAuth}
      data-codex-host-token-len={tokenProbe.len}
      data-codex-host-token-count={tokenProbe.count}
      data-codex-host-phase={phase}
      data-codex-host-source={target.source}
    >
      {/*
        外壳**不再自绘 52px 工作区头**（2026-10-13 实测：外壳的 header 52px + 访客自己的
        threadHeader 52px 叠成「双头」，并把主内容整体下推 52px，与官方首页
        [52,44,1224,768] 的几何不符）。官方首页那一行里只有右侧一个动作钮，
        标题/动作都在页面内 —— 那由访客自己渲染。访客上报的标题仍写进 host-store
        （导轨选中态、窗口标题用它）。
      */}
      {notice == null ? null : (
        <p className="codex-host__notice" role="status">
          {notice}
        </p>
      )}

      <div className="codex-host__stage">
        <iframe
          className="codex-host__frame"
          key={attempt}
          onLoad={handleLoad}
          ref={frameRef}
          src={target.url}
          title={title}
        />
        {phase === "ready" ? null : (
          <div aria-live="polite" className="codex-host__overlay" role="status">
            {phase === "loading" ? (
              <>
                <span aria-hidden className="codex-host__spinner" />
                <p className="codex-host__overlay-title">正在连接 {target.url}</p>
              </>
            ) : (
              <>
                <p className="codex-host__overlay-title">没有连上被托管的本地应用</p>
                <p className="codex-host__overlay-body">
                  地址：{target.url}（来源：
                  {target.source === "query" ? "URL 参数" : target.source === "env" ? "构建变量" : "默认值"}）
                </p>
                <p className="codex-host__overlay-body">
                  请确认该应用已启动；若它的地址不是这个，请带上 {"`?artex=<地址>`"} 再打开本页。
                </p>
                <div className="codex-host__overlay-actions">
                  <button className="codex-host__retry" onClick={retry} type="button">
                    重试
                  </button>
                  <a className="codex-host__action" href={target.url} rel="noreferrer" target="_blank">
                    在浏览器打开
                  </a>
                </div>
              </>
            )}
          </div>
        )}
      </div>
    </div>
  );
}