export type ShortcutSectionId = "composer" | "thread" | "app";

export interface ShortcutRow {
  id: string;
  /** 官方菜单文案 */
  label: string;
  /** 官方快捷键文案（SPEC 原文，保留 Ctrl / Shift / Alt 写法）；空串 = 官方未实测/未分配 */
  chord: string;
  /** 出处：SPEC 的哪一节 */
  source: "SPEC §4" | "SPEC §5";
  /** 备注（官方原文里的英文条目在这里保留原样；也可写「未实测」说明） */
  note?: string;
  /** 官方分区（消息 id section.composer / thread / app） */
  section: ShortcutSectionId;
  /** 官方行（消息目录里能确证的行），否则是本工程从应用菜单补的行 */
  official?: boolean;
}

export interface ShortcutGroup {
  id: ShortcutSectionId;
  label: string;
  rows: ShortcutRow[];
}

