/* ── 用户改写过的键位（localStorage；官方这一页可改键，所以这里是真的可改）───────── */

const STORAGE_KEY = "codex.settings.shortcuts";

function readOverrides(): Record<string, string> {
  if (typeof window === "undefined") return {};
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    if (!raw) return {};
    const parsed: unknown = JSON.parse(raw);
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) return {};
    const out: Record<string, string> = {};
    for (const [key, value] of Object.entries(parsed as Record<string, unknown>)) {
      if (typeof value === "string") out[key] = value;
    }
    return out;
  } catch {
    return {};
  }
}

let overrides: Record<string, string> = readOverrides();
const listeners = new Set<() => void>();

function commit(next: Record<string, string>) {
  overrides = next;
  try {
    // 没有任何改写 ⇒ 不留键（与 store.ts「默认档不写存储」同一口径）。
    // 「重置为默认设置」之后 localStorage 里干净地没有 codex.settings.shortcuts，
    // 而不是留一个 "{}"。
    if (Object.keys(next).length === 0) window.localStorage.removeItem(STORAGE_KEY);
    else window.localStorage.setItem(STORAGE_KEY, JSON.stringify(next));
  } catch {
    // 配额满 / 禁用：内存里照样生效
  }
  for (const listener of listeners) listener();
}

export function getShortcutOverrides(): Record<string, string> {
  return overrides;
}

export function subscribeShortcuts(listener: () => void): () => void {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

/** 某条捷径的当前键位（用户改写优先） */
export function shortcutChord(row: ShortcutRow, map: Record<string, string> = overrides): string {
  return map[row.id] ?? row.chord;
}

export function setShortcutChord(id: string, chord: string) {
  const next = { ...overrides };
  const row = ROWS.find((item) => item.id === id);
  if (!chord || (row && chord === row.chord)) delete next[id];
  else next[id] = chord;
  commit(next);
}

/** 「恢复默认快捷键」/「全部重置为默认值」共用：清掉全部改写 */
export function resetAllShortcuts() {
  commit({});
}

/** React 绑定：返回 { map, setChord, resetAll, dirty } */
export function useShortcutBindings() {
  const map = useSyncExternalStore(subscribeShortcuts, getShortcutOverrides, getShortcutOverrides);
  const setChord = useCallback((id: string, chord: string) => setShortcutChord(id, chord), []);
  const resetAll = useCallback(() => resetAllShortcuts(), []);
  return { map, setChord, resetAll, dirty: Object.keys(map).length > 0 };
}

/** 把 KeyboardEvent 归一成官方文案口径的 chord 字符串（Ctrl+Shift+S / F11 / Ctrl+`） */
export function normalizeChord(event: KeyboardEvent): string {
  const parts: string[] = [];
  if (event.ctrlKey) parts.push("Ctrl");
  if (event.altKey) parts.push("Alt");
  if (event.shiftKey) parts.push("Shift");
  if (event.metaKey) parts.push("Meta");

  const key = event.key;
  const isModifierOnly = ["Control", "Alt", "Shift", "Meta"].includes(key);
  if (isModifierOnly) return parts.join("+");

  const map: Record<string, string> = {
    ArrowLeft: "←",
    ArrowRight: "→",
    ArrowUp: "↑",
    ArrowDown: "↓",
    " ": "Space",
    Escape: "Esc",
    Enter: "Enter",
    "+": "=",
  };
  let label = map[key] ?? key;
  if (label.length === 1 && event.shiftKey && /[a-zA-Z]/.test(label)) label = label.toUpperCase();
  parts.push(label);
  return parts.join("+");
}

/** 与官方文案做宽松比较：忽略大小写、空格 */
export function chordEquals(a: string, b: string) {
  const norm = (value: string) => value.toLowerCase().replace(/\s+/g, "");
  return norm(a) === norm(b);
}

export function findShortcutByChord(chord: string): ShortcutRow | undefined {
  return ROWS.find((row) => row.chord && chordEquals(row.chord, chord));
}

/**
 * 真实按键捕获：录音期间全局监听 keydown，命中官方快捷键时返回该行。
 * 用于「快捷键」分区的「按一下试试」区域 —— 这是真监听，不是展示动画。
 */
export function useChordCapture() {
  const [recording, setRecording] = useState(false);
  const [chord, setChord] = useState<string | null>(null);
  const [matched, setMatched] = useState<ShortcutRow | null>(null);
  const listenerRef = useRef<((event: KeyboardEvent) => void) | null>(null);

  const stop = useCallback(() => {
    setRecording(false);
  }, []);

  const start = useCallback(() => {
    setChord(null);
    setMatched(null);
    setRecording(true);
  }, []);

  useEffect(() => {
    if (!recording) return;
    const onKeyDown = (event: KeyboardEvent) => {
      const next = normalizeChord(event);
      if (!next) return;
      event.preventDefault();
      event.stopPropagation();
      setChord(next);
      setMatched(findShortcutByChord(next) ?? null);
      if (!["Control", "Alt", "Shift", "Meta"].includes(event.key)) setRecording(false);
    };
    listenerRef.current = onKeyDown;
    window.addEventListener("keydown", onKeyDown, true);
    return () => window.removeEventListener("keydown", onKeyDown, true);
  }, [recording]);

  return { recording, chord, matched, start, stop };
}

/**
 * 设置页自己负责的两条官方快捷键（SPEC §5 编辑 / 帮助）：
 *   Ctrl+,   打开设置（常规）
 *   Ctrl+/   显示键盘快捷键
 * 其余快捷键属于外壳与对话面（cx-shell / cx-chat），由它们的 owner 注册。
 * 这个 hook 只注册自己这两条，并且**不劫持输入框里的按键**。
 */
export function useSettingsShortcuts(enabled = true) {
  const navigate = useNavigate();

  useEffect(() => {
    if (!enabled) return;
    const onKeyDown = (event: KeyboardEvent) => {
      if (!event.ctrlKey || event.altKey || event.metaKey) return;
      const target = event.target as HTMLElement | null;
      const isEditable =
        target instanceof HTMLElement &&
        (target.isContentEditable || ["INPUT", "TEXTAREA", "SELECT"].includes(target.tagName));

      if (event.key === ",") {
        event.preventDefault();
        navigate(`/settings/${DEFAULT_SETTINGS_SECTION}`);
        return;
      }
      if (event.key === "/" && !isEditable) {
        event.preventDefault();
        navigate("/settings/shortcuts");
      }
    };
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [enabled, navigate]);
}
