/**
 * 宿主 ↔ guest 的消息通道（postMessage 协议 v1）。
 *
 * 为什么用 postMessage 而不是 IPC：guest 是**独立进程/独立技术栈**的 Next.js 应用，宿主与它
 * 之间只有浏览器这一层共识（同源策略 + window 消息）。走 Electron IPC 会把 guest 绑死在
 * Electron 里，dev 态（浏览器里开 `next dev`）就复现不了。
 *
 * 信封（两侧必须逐字一致）：
 *   { channel: "codex-host", v: 1, type, id?, payload? }
 *
 * 方向与类型：
 *   host → guest : codex-host:init | :theme | :navigate | :panel | :ping
 *   guest → host : codex-host:ready | :route | :theme-request | :notify | :error | :pong
 *
 * 三条不变量（少一条就会出现「看起来连上了但状态是错的」）：
 *   1. 只认配置里那个 origin，且**必须**是那个 iframe 发来的（防同页其它帧冒名）；
 *   2. 只认本通道 + 本版本的信封，其它消息一律不动；
 *   3. send 永远不抛 —— guest 还没挂载/已经卸载都要静默失败（返回 false）。
 */

export const HOST_CHANNEL = "codex-host";
export const HOST_PROTOCOL_VERSION = 1;

export type HostToGuestType =
  | "codex-host:init"
  | "codex-host:theme"
  | "codex-host:navigate"
  // 菜单栏「显示/隐藏侧边栏」要作用到访客的面板（托管档下面板归访客画）；
  // 载荷 { toggle: true }。访客不认识就按协议忽略（向前兼容）——老版本安全。
  | "codex-host:panel"
  | "codex-host:ping";

export type GuestToHostType =
  | "codex-host:ready"
  // 访客把它的 access token 交给外壳：外壳要**自己直连 ARTEX API** 渲染原生页面
  // （后端 CORS = `*`，见 server/server.go 的 cors()），而 token 只存在访客 origin 的 localStorage。
  | "codex-host:token"
  | "codex-host:route"
  | "codex-host:theme-request"
  | "codex-host:notify"
  | "codex-host:error"
  | "codex-host:pong";

export interface HostEnvelope {
  channel: string;
  v: number;
  type: string;
  id?: string;
  payload?: unknown;
}

/** 信封形状校验；不是本通道/本版本的一律判否。 */
export function isHostEnvelope(data: unknown): data is HostEnvelope {
  if (typeof data !== "object" || data === null) return false;
  const e = data as Record<string, unknown>;
  return (
    e.channel === HOST_CHANNEL &&
    e.v === HOST_PROTOCOL_VERSION &&
    typeof e.type === "string" &&
    e.type.startsWith("codex-host:")
  );
}

export interface GuestReadyPayload {
  version: string;
  route: string;
  title: string;
}

/** `codex-host:token` — 访客的 access token（空串 = 未登录）。 */
export interface GuestTokenPayload {
  token?: string;
}

export interface GuestRoutePayload {
  path: string;
  title: string;
}

export interface GuestNotifyPayload {
  level: "info" | "warn" | "error";
  message: string;
}

export interface GuestErrorPayload {
  message: string;
  source?: string;
}

export interface HostBridgeHandlers {
  onReady?: (payload: GuestReadyPayload) => void;
  /** 访客交来的 access token（空串 = 未登录）；外壳据此直连 ARTEX API。 */
  onToken?: (payload: GuestTokenPayload) => void;
  onRoute?: (payload: GuestRoutePayload) => void;
  onThemeRequest?: () => void;
  onNotify?: (payload: GuestNotifyPayload) => void;
  onError?: (payload: GuestErrorPayload) => void;
  onPong?: (payload: { t: number }) => void;
}

export interface HostBridge {
  /** 卸载：摘掉 message 监听。**必须**在组件卸载时调用。 */
  dispose: () => void;
  send: (type: HostToGuestType, payload?: unknown) => boolean;
  /**
   * 握手首帧：主题 + 令牌快照。iframe load 后发一次，收到 theme-request 再补发一次。
   * 主题由调用方传入（宿主自己知道 `mode/resolved`，不该让桥去 DOM 里猜）。
   */
  sendInit: (theme?: { mode: string; resolved: string }) => boolean;
  navigate: (path: string) => boolean;
  /**
   * 幂等收起访客面板（`codex-host:panel {open:false}`）：
   * 外壳自己画 288px 面板时（对话页的混合档），要求访客把自己的面板收起来。
   */
  collapsePanel: () => boolean;
}

export function createHostBridge(options: {
  getFrame: () => HTMLIFrameElement | null;
  guestOrigin: string;
  handlers: HostBridgeHandlers;
}): HostBridge {
  const { getFrame, guestOrigin, handlers } = options;

  function send(type: HostToGuestType, payload?: unknown): boolean {
    const win = getFrame()?.contentWindow;
    if (!win) return false;
    try {
      win.postMessage({ channel: HOST_CHANNEL, v: HOST_PROTOCOL_VERSION, type, payload }, guestOrigin);
      return true;
    } catch {
      // 跨源写入被拒（guest 正在导航/已销毁）时不要炸掉宿主，交给超时兜底。
      return false;
    }
  }

  function onMessage(event: MessageEvent): void {
    if (event.origin !== guestOrigin) return;
    const frame = getFrame();
    // 同页可能还有别的帧（沙箱帧等）：只认我们自己那一个 iframe。
    if (frame && event.source !== frame.contentWindow) return;
    if (!isHostEnvelope(event.data)) return;
    const { type, payload } = event.data;
    switch (type as GuestToHostType) {
      case "codex-host:ready":
        handlers.onReady?.(payload as GuestReadyPayload);
        break;
      case "codex-host:route":
        handlers.onRoute?.(payload as GuestRoutePayload);
        break;
      case "codex-host:token":
        handlers.onToken?.(payload as GuestTokenPayload);
        break;
      case "codex-host:theme-request":
        handlers.onThemeRequest?.();
        break;
      case "codex-host:notify":
        handlers.onNotify?.(payload as GuestNotifyPayload);
        break;
      case "codex-host:error":
        handlers.onError?.(payload as GuestErrorPayload);
        break;
      case "codex-host:pong":
        handlers.onPong?.(payload as { t: number });
        break;
      default:
        break;
    }
  }

  window.addEventListener("message", onMessage);
  return {
    dispose: () => window.removeEventListener("message", onMessage),
    send,
    sendInit: (theme) => send("codex-host:init", buildInitPayload(theme)),
    navigate: (path: string) => send("codex-host:navigate", { path }),
    collapsePanel: () => send("codex-host:panel", { open: false }),
  };
}

/**
 * 主题令牌快照：把宿主当前的 CSS 自定义属性读出来交给 guest。
 * 只带 `--color-*` / `--radius-*` / `--font-*` 这类**语义令牌**，不带布局私有变量 ——
 * guest 需要的是「你的设计系统长什么样」，不是宿主的实现细节。
 */
export function snapshotThemeTokens(limit = 400): Record<string, string> {
  const out: Record<string, string> = {};
  const style = getComputedStyle(document.documentElement);
  for (let i = 0; i < style.length && Object.keys(out).length < limit; i += 1) {
    const name = style.item(i);
    if (!/^--(color|radius|font|shadow)-/.test(name)) continue;
    const value = style.getPropertyValue(name).trim();
    if (value !== "") out[name] = value;
  }
  return out;
}

function buildInitPayload(theme?: { mode: string; resolved: string }): {
  theme: { mode: string; resolved: string };
  tokens: Record<string, string>;
} {
  const root = document.documentElement;
  const fromDom = root.classList.contains("dark") || root.dataset.theme === "dark" ? "dark" : "light";
  return {
    theme: theme ?? { mode: fromDom, resolved: fromDom },
    tokens: snapshotThemeTokens(),
  };
}

export { buildInitPayload };