import { useSyncExternalStore } from "react";
import { useNavigate, useSearchParams } from "react-router-dom";

import { useArtexQuery } from "@/api/artex";
import { CodexNewChat } from "@/icons";
import { cn } from "@/lib/utils";
import { PanelPortal } from "@/shell/panel-slot";
import { getHostGuest, navigateGuest, subscribeHostGuest } from "@/shell/host/host-store";

/**
 * 对话页的**外壳原生面板**（rail「对话」→ /artex 的混合档 / 外壳会话态）。
 *
 * ⚠️ 结构与类名**逐条对齐外壳自己的面板**（`src/shell/SidebarPanel.tsx`），不新造类：
 *   `.codex-panel__nav-list` › `.codex-panel__new-chat`（官方「新聊天」行，272×30 / 8% 底 / r12.5）
 *   `.codex-panel__section.codex-panel__section--recent` › `.codex-panel__section-head` + `__section-title`「最近」
 *   `.codex-panel__nav-list--body` › `.codex-panel__row-wrap` › `.codex-panel__row`（`.is-active`）› `__row-label`
 *   空态用 `.codex-panel__empty`。
 * 2026-10-13 修正：此前这里用了不存在的 `codex-panel__row-icon` 与自写的 `<p className="cx-muted">`，
 * 所以面板看着「不像官方」——现在全部换成官方类。
 *
 * `mode`：会话列表把点击送到哪里。
 *  · `"guest"`（默认）：混合档 —— 外壳画面板、访客画主面，点行让**访客**切会话；
 *  · `"shell"`：外壳原生会话态（/artex-chat）—— 点行切**外壳自己的路由**，选中态读当前 URL。
 */

interface Conversation {
  id: string | number;
  title?: string;
  agent_key?: string;
}

interface ConversationsResponse {
  conversations?: Conversation[];
}

function activeConversationId(route: string | null): string | null {
  if (!route) return null;
  const query = route.indexOf("?");
  if (query < 0) return null;
  return new URLSearchParams(route.slice(query + 1)).get("c");
}

export function ArtexChatPanel({ mode = "guest" }: { mode?: "guest" | "shell" }) {
  const { data } = useArtexQuery<ConversationsResponse | Conversation[]>("/api/conversations");
  const guest = useSyncExternalStore(subscribeHostGuest, getHostGuest);
  const navigate = useNavigate();
  const [params] = useSearchParams();

  const list = Array.isArray(data) ? data : (data?.conversations ?? []);
  const active = mode === "shell" ? params.get("c") : activeConversationId(guest.route);

  const go = (id: string | null) => {
    if (mode === "shell") {
      navigate(id == null ? "/artex-chat" : "/artex-chat?c=" + encodeURIComponent(id));
      return;
    }
    navigateGuest(id == null ? "/chat" : "/chat?c=" + encodeURIComponent(id));
  };

  return (
    <PanelPortal>
      <div className="codex-panel__nav-list">
        {/* 用 <a> 而不是 <button>：官方面板这两处都是 NavLink（SidebarPanel.tsx:406 / :440）。
            <button> 的 UA 默认 `text-align:center` 会把短标题居中（实测 label textAlign=center），
            看起来像「缩进」—— 换回官方元素类型即消除。 */}
        <a className="codex-panel__new-chat" href="#" onClick={(event) => { event.preventDefault(); go(null); }}>
          <CodexNewChat size={20} />
          <span>{mode === "shell" ? "全部对话" : "新聊天"}</span>
        </a>
      </div>

      <section className="codex-panel__section codex-panel__section--recent">
        <div className="codex-panel__section-head">
          <span className="codex-panel__section-title">最近</span>
        </div>
        <div className="codex-panel__nav-list codex-panel__nav-list--body">
          {list.length === 0 ? <div className="codex-panel__empty">无聊天</div> : null}
          {list.map((conversation) => {
            const id = String(conversation.id);
            return (
              <div className="codex-panel__row-wrap" key={id}>
                <a
                  aria-current={active === id ? "page" : undefined}
                  className={cn("codex-panel__row", active === id && "is-active")}
                  href="#"
                  onClick={(event) => {
                    event.preventDefault();
                    go(id);
                  }}
                >
                  <span className="codex-panel__row-label">
                    {(conversation.title ?? "").trim() || "新对话"}
                  </span>
                </a>
              </div>
            );
          })}
        </div>
      </section>
    </PanelPortal>
  );
}