/**
 * ARTEX API 客户端（外壳侧直连）。
 *
 * 为什么外壳要自己调 API：桌面端的方向已从「外壳托管控制台 iframe」转为
 * 「**外壳自己渲染原生页面 + 直连 ARTEX API**」——只有这样才能做到「页面就是壳的代码」。
 *
 * 三件事决定了这套调用可行：
 *   1. 后端对 /api/* 的 CORS 是 `*`（server/server.go 的 cors()，实测 OPTIONS/GET 都带
 *      `Access-Control-Allow-Origin: *`）；
 *   2. token 由访客经 `codex-host:token` 推给外壳（访客 origin 的 localStorage 外壳读不到，
 *      见 host-store 与 web/src/codex-host/protocol.ts）；
 *   3. 访客 origin 就是 API origin（生产态 = http://127.0.0.1:8787）。
 *
 * 未附着访客 / 未登录时一律抛 ArtexApiError，**不猜**、不静默返回空数据（页面据此显示真实状态）。
 */
import { useEffect, useState } from "react";

import { getHostGuest, subscribeHostGuest } from "@/shell/host/host-store";

export class ArtexApiError extends Error {
  readonly status: number;

  constructor(status: number, message: string) {
    super(message);
    this.name = "ArtexApiError";
    this.status = status;
  }
}

export function artexApiOrigin(): string | null {
  return getHostGuest().apiOrigin;
}

/** 可用 token；空串（未登录）按不可用处理。 */
export function artexToken(): string | null {
  const token = getHostGuest().token;
  return token != null && token.length > 0 ? token : null;
}

export interface ArtexRequestInit {
  method?: "GET" | "POST" | "PUT" | "PATCH" | "DELETE";
  body?: unknown;
  signal?: AbortSignal;
  headers?: Record<string, string>;
}

/** 一次 ARTEX API 调用；非 2xx 抛 ArtexApiError（带 status 与响应体文本）。 */
export async function artexFetch<T>(path: string, init: ArtexRequestInit = {}, attempts = 0): Promise<T> {
  const origin = artexApiOrigin();
  if (origin == null) throw new ArtexApiError(0, "宿主尚未附着访客（API origin 未知）");
  const token = artexToken();
  const headers: Record<string, string> = { ...init.headers };
  if (init.body !== undefined) headers["content-type"] = "application/json";
  if (token != null) headers.authorization = `Bearer ${token}`;

  const response = await fetch(`${origin}${path.startsWith("/") ? path : `/${path}`}`, {
    method: init.method ?? "GET",
    headers,
    body: init.body === undefined ? undefined : JSON.stringify(init.body),
    signal: init.signal,
  });

  if (!response.ok) {
    const detail = await response.text().catch(() => "");
    /*
     * 401 竞态兜底（真机实测）：外壳启动/切页时，访客（静默控制台）的 token 可能还没推到，
     * 或推来的是控制台刷新前的旧值 —— 页面首帧就会拿到 401，而用户看到的是「加载失败」。
     * 这里对 401 再试两次（间隔 1.2s）：等访客的心跳把新 token 推上来（心跳 = 10s 一轮，
     * 且只在值变化时发），第二次通常就成功了。
     * 仍然失败就如实抛错 —— 页面显示真实的 401 状态，不做假的成功。
     */
    if (response.status === 401 && attempts < 2) {
      await new Promise((resolve) => setTimeout(resolve, 1200));
      return artexFetch<T>(path, init, attempts + 1);
    }
    throw new ArtexApiError(response.status, detail.length > 0 ? detail.slice(0, 400) : response.statusText);
  }
  if (response.status === 204) return undefined as T;
  const text = await response.text();
  if (text.length === 0) return undefined as T;
  return JSON.parse(text) as T;
}

export interface ArtexQueryState<T> {
  data: T | null;
  error: ArtexApiError | null;
  loading: boolean;
  reload: () => void;
}

/**
 * 最小的只读查询 hook：监听 host-store（token / origin 就绪后自动重取），
 * 供页面用它读 ARTEX 数据。写操作直接用 artexFetch。
 */
export function useArtexQuery<T>(path: string | null): ArtexQueryState<T> {
  const [data, setData] = useState<T | null>(null);
  const [error, setError] = useState<ArtexApiError | null>(null);
  const [loading, setLoading] = useState(false);
  const [nonce, setNonce] = useState(0);
  const [ready, setReady] = useState(() => artexApiOrigin() != null && artexToken() != null);
  // token 换了新值也要重取：访客有心跳（每 10s 推一次变化值），控制台刷新令牌后外壳据此自动重取。
  const [token, setToken] = useState<string | null>(() => artexToken());

  useEffect(
    () =>
      subscribeHostGuest(() => {
        setReady(artexApiOrigin() != null && artexToken() != null);
        setToken(artexToken());
      }),
    [],
  );

  useEffect(() => {
    if (path == null || !ready) return;
    let cancelled = false;
    setLoading(true);
    artexFetch<T>(path)
      .then((value) => {
        if (cancelled) return;
        setData(value);
        setError(null);
      })
      .catch((cause: unknown) => {
        if (cancelled) return;
        setError(cause instanceof ArtexApiError ? cause : new ArtexApiError(0, String(cause)));
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [path, ready, nonce, token]);

  return { data, error, loading, reload: () => setNonce((n) => n + 1) };
}