import { useCallback, useEffect, useMemo, useRef, useState } from "react";

import { artexFetch, useArtexQuery } from "@/api/artex";
import { Composer, Message as ChatMessage, useComposerSelection } from "@/chat";
import { useNavigate } from "react-router-dom";

import { WorkspaceHeader } from "@/shell";
import { ArtexChatPanel } from "@/shell/host/ArtexChatPanel";
import { CodexScrollToBottom } from "@/icons";
import { Button } from "@/ui";
import { useSearchParams } from "react-router-dom";

import { Badge, EmptyState, RowSkeleton } from "./parts";

/**
 * 外壳原生**会话态**（路由 /artex-chat?c=<id>）—— objective ② 里 chat 的第二步。
 *
 * 数据（全部直连 ARTEX API，接口以控制台 src/lib/api.ts 为准）：
 *  · `GET  /api/conversations`                     → { conversations }
 *  · `GET  /api/conversations/{id}/messages?since=N` → { items: Activity[], cursor, running }
 *  · `POST /api/conversations/{id}/messages`       → { status }（body: { message, attachments }）
 * **没有 SSE**：控制台自己就是「先全量、再 since=cursor 轮询」，外壳照同样的节奏做，行为一致。
 *
 *
 * ⚠️ 上 rail 之前还差两道闸（2026-10-13 实测记录）：
 *  1. **快乐路径未验证**：发送链路已用「不存在的会话 id」端到端跑通（Composer 输入 → 官方发送钮 →
 *     我的 send() → POST /api/conversations/{id}/messages → 后端 404 如实回显），
 *     但「真实会话里发一条 → 模型回复 → 轮询渲染」会消耗真实 LLM 调用，**需用户点头**才能验。
 *  2. **Composer 的芯片尚未接 ARTEX**：官方 Composer 自带「完全访问」「5.6 Sol Ultra」等芯片，
 *     我们只把 `selection` 透传进去渲染，**没有**把它映射到 ARTEX 的会话设置（模型对应
 *     `PATCH /api/conversations/{id}/profile`，权限在 ARTEX 侧没有等价物）。
 *     ⇒ 在这两条解决前，rail「对话」保持混合档（外壳面板 + 访客主面），不让「看着对但点了没用」上线。
 * 本轮只做「读 + 发」的最小闭环，用于验证外壳能否承担会话态；
 * 消息渲染暂按 worker 分组的纯文本（控制台的 transcript 有工具块/markdown 等更丰富的呈现，属后续项）。
 */

interface Activity {
  seq: number;
  worker?: string;
  ts?: string;
  kind?: string;
  tool?: string;
  tool_use_id?: string;
  is_error?: boolean;
  summary?: string;
  detail?: string;
}

interface Conversation {
  id: number | string;
  title?: string;
  agent_key?: string;
  /** ARTEX 会话当前使用的 LLM Profile（芯片显示它）。 */
  llm_profile_id?: number | null;
}

interface MessagesResponse {
  items?: Activity[];
  cursor?: number;
  running?: boolean;
}

/** 外壳 <Message> 的 message 参数类型（从组件签名推导，避免再写一遍模型）。 */
type ShellMessage = Parameters<typeof ChatMessage>[0]["message"];

/**
 * ARTEX `Activity` → 外壳 `Message`。
 *
 * 映射口径对齐控制台的 transcript（src/components/transcript.tsx 的 kind 分支）：
 *   user / intent                → 用户消息；
 *   text / result                → 助手正文；
 *   thinking                     → 挂到紧随其后的助手消息的 `reasoning`（外壳会渲染成可折叠思考块）；
 *   tool_use                     → 助手消息的 `toolCalls`（外壳渲染成工具调用块）；
 *   tool_result                  → 回填到上一条 toolCall 的 output，失败则标 error；
 *   usage / round / intercept…   → 不渲染（控制台也跳过 usage）。
 *
 * 这样消息的**呈现**（气泡、markdown、思考块、工具块）全部走外壳自己的代码。
 */
function toShellMessages(activities: Activity[], conversationId: string): ShellMessage[] {
  const out: ShellMessage[] = [];
  let pendingReasoning = "";

  for (const activity of activities) {
    const kind = (activity.kind ?? "").trim();
    const summary = (activity.summary ?? "").trim();
    const createdAt = activity.ts ?? new Date().toISOString();

    if (kind === "usage" || kind === "round" || kind === "intercept_request") continue;

    if (kind === "thinking") {
      pendingReasoning = pendingReasoning === "" ? summary : pendingReasoning + "\n\n" + summary;
      continue;
    }

    if (kind === "user" || kind === "intent") {
      out.push({
        id: "a" + activity.seq,
        conversationId,
        role: "user",
        content: summary,
        createdAt,
      });
      continue;
    }

    if (kind === "tool_use") {
      out.push({
        id: "a" + activity.seq,
        conversationId,
        role: "assistant",
        content: "",
        createdAt,
        reasoning: pendingReasoning === "" ? undefined : pendingReasoning,
        toolCalls: [
          {
            id: activity.tool_use_id ?? "a" + activity.seq,
            name: activity.tool ?? "tool",
            summary: summary,
            status: activity.is_error ? "error" : "success",
          },
        ],
      });
      pendingReasoning = "";
      continue;
    }

    if (kind === "tool_result") {
      for (let i = out.length - 1; i >= 0; i -= 1) {
        const target = out[i];
        const calls = target.toolCalls;
        if (calls && calls.length > 0) {
          target.toolCalls = calls.map((call, index) =>
            index === calls.length - 1
              ? {
                  ...call,
                  output: activity.detail ?? summary,
                  status: activity.is_error ? ("error" as const) : ("success" as const),
                }
              : call,
          );
          break;
        }
      }
      continue;
    }

    // 其余（text / result / 未知 kind）当助手正文；正文为空但有 detail 时用 detail。
    const content = summary !== "" ? summary : (activity.detail ?? "").trim();
    if (content === "" && pendingReasoning === "") continue;
    out.push({
      id: "a" + activity.seq,
      conversationId,
      role: "assistant",
      content,
      createdAt,
      reasoning: pendingReasoning === "" ? undefined : pendingReasoning,
    });
    pendingReasoning = "";
  }

  return out;
}

const WORKER_LABEL: Record<string, string> = {
  planner: "规划",
  mainagent: "主助手",
};

function workerLabel(worker: string | undefined): string {
  const key = (worker ?? "").trim();
  if (!key) return "系统";
  if (WORKER_LABEL[key]) return WORKER_LABEL[key];
  const workerMatch = /^work#(\d+)$/.exec(key);
  if (workerMatch) return "执行 #" + workerMatch[1];
  return key;
}

export function ArtexChatRoute() {
  const [params, setParams] = useSearchParams();
  const navigate = useNavigate();
  const conversationId = params.get("c");

  const conversations = useArtexQuery<{ conversations?: Conversation[] }>("/api/conversations");
  /** ARTEX 的模型清单（LLM Profile）：注入官方模型芯片，芯片仍是官方件、数据是宿主的。 */
  const profiles = useArtexQuery<{ profiles?: { id: number | string; name?: string; model?: string }[] }>(
    "/api/llm/profiles",
  );
  const list = conversations.data?.conversations ?? [];

  const [items, setItems] = useState<Activity[]>([]);
  const [cursor, setCursor] = useState(0);
  const [running, setRunning] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [sending, setSending] = useState(false);
  /** 窗口化：1451 条一次性渲染会卡（实测），只挂最后 200 条，其它按需展开。 */
  const [windowSize, setWindowSize] = useState(200);
  /**
   * 长会话滚动体验（第三十轮遗留项）：
   *  · 用户**在底部附近**时才自动跟随最新（否则读历史会被打断）；
   *  · 不在底部时给一个「跳到最新」的浮出按钮。
   */
  const [nearBottom, setNearBottom] = useState(true);
  /** 官方 Composer 的芯片选择（权限/模型/力度/项目）——用它渲染输入区的官方控件，不自己拼。 */
  const baseSelection = useComposerSelection();
/**
   * 会话态输入区的选择：模型部分接 ARTEX —— 选中即可 `PATCH /api/conversations/{id}/profile`；
   * 权限档 ARTEX 没有等价物 ⇒ 传 `hidePermission` 如实隐藏（不摆一个点了没用的官方芯片）。
   */
  const patchProfile = useCallback(
    async (id: string) => {
      if (!conversationId) return;
      try {
        await artexFetch("/api/conversations/" + encodeURIComponent(conversationId) + "/profile", {
          method: "PATCH",
          body: { llm_profile_id: Number(id) },
        });
        conversations.reload();
      } catch (cause) {
        setError(cause instanceof Error ? cause.message : String(cause));
      }
    },
    [conversationId, conversations],
  );
  const currentProfileId = useMemo(() => {
    const found = list.find((item) => String(item.id) === conversationId);
    return found && found.llm_profile_id != null ? String(found.llm_profile_id) : null;
  }, [conversationId, list]);

  const modelOptions = useMemo(
    () => (profiles.data?.profiles ?? []).map((profile) => ({
      id: String(profile.id),
      label: (profile.name ?? "").trim() || profile.model || ("Profile " + String(profile.id)),
    })),
    [profiles.data],
  );
  const composerSelection = useMemo(
    () => {
      const option =
        modelOptions.find((item) => item.id === currentProfileId) ?? modelOptions[0] ?? null;
      return {
        ...baseSelection,
        // 芯片上的当前档文案取自 selection.model（官方 useComposerSelection 是按它自己的 7 项解析的），
        // 所以这里用 ARTEX 的 profile 覆盖它，否则芯片会显示官方模型名。
        model: option ?? baseSelection.model,
        modelId: option ? option.id : baseSelection.modelId,
        setModelId: (id: string) => {
          baseSelection.setModelId(id);
          void patchProfile(id);
        },
      };
    },
    [baseSelection, currentProfileId, modelOptions, patchProfile],
  );

  const scrollRef = useRef<HTMLDivElement | null>(null);
  const bottomRef = useRef<HTMLDivElement | null>(null);

  const load = useCallback(async (id: string, since: number) => {
    const page = await artexFetch<MessagesResponse>(
      "/api/conversations/" + encodeURIComponent(id) + "/messages?since=" + String(since),
    );
    const next = page.items ?? [];
    setItems((prev) => (since === 0 ? next : [...prev, ...next]));
    setCursor(page.cursor ?? since);
    setRunning(!!page.running);
    return next.length;
  }, []);

  // 切换会话：清空后全量拉一次
  useEffect(() => {
    if (!conversationId) {
      setItems([]);
      setCursor(0);
      setRunning(false);
      return;
    }
    let alive = true;
    setLoading(true);
    setError(null);
    load(conversationId, 0)
      .catch((cause: unknown) => {
        if (alive) setError(cause instanceof Error ? cause.message : String(cause));
      })
      .finally(() => {
        if (alive) setLoading(false);
      });
    return () => {
      alive = false;
    };
  }, [conversationId, load]);

  // 轮询：跑着的时候 1.5s 一次（与控制台同节奏），空闲 5s 拉一次心跳
  useEffect(() => {
    if (!conversationId) return;
    const timer = window.setInterval(
      () => {
        load(conversationId, cursor).catch(() => {});
      },
      running ? 1500 : 5000,
    );
    return () => window.clearInterval(timer);
  }, [conversationId, cursor, running, load]);

  /** 贴底判定：距底 < 120px 视为「在看最新」。 */
  const handleScroll = useCallback(() => {
    const node = scrollRef.current;
    if (!node) return;
    setNearBottom(node.scrollHeight - node.scrollTop - node.clientHeight < 24);
  }, []);

  /** 用**滚动容器**贴底，而不是 scrollIntoView(bottomRef)：
   *  bottomRef 之后还有「跳到最新」条与输入区，scrollIntoView 只会把哨兵滚进视野，
   *  容器距底仍差一段 ⇒ 「已到最新」的判定永远为假（实测）。 */
  useEffect(() => {
    if (!nearBottom) return;
    const node = scrollRef.current;
    if (node) node.scrollTop = node.scrollHeight;
  }, [items.length, nearBottom, windowSize]);

  const jumpToLatest = useCallback(() => {
    setNearBottom(true);
    // 用瞬时滚动：smooth 期间还会触发 scroll 事件，容易把 nearBottom 又翻回 false（实测点了没到底）。
    const node = scrollRef.current;
    if (node) node.scrollTop = node.scrollHeight;
  }, []);

  /**
   * 发送。**没有选中会话时先懒创建**（与控制台的流程一致：createConversation("auto", "") 再发消息）——
   * 这样「新聊天」不需要额外的入口，也不会先建出一堆空会话。
   */
  const send = useCallback(async (text: string) => {
    const message = text.trim();
    if (message === "") return;
    setSending(true);
    setError(null);
    try {
      let target = conversationId;
      if (!target) {
        const created = await artexFetch<{ id: number | string }>("/api/conversations", {
          method: "POST",
          body: { agent_key: "auto", title: "", llm_profile_id: null },
        });
        target = String(created.id);
        conversations.reload();
        setParams({ c: target });
      }
      await artexFetch("/api/conversations/" + encodeURIComponent(target) + "/messages", {
        method: "POST",
        body: { message, attachments: [] },
      });
      await load(target, 0);
    } catch (cause) {
      setError(cause instanceof Error ? cause.message : String(cause));
    } finally {
      setSending(false);
    }
  }, [conversationId, conversations, load, setParams]);

  const active = useMemo(
    () => list.find((conversation) => String(conversation.id) === conversationId),
    [conversationId, list],
  );

  /** 页头标题：官方会话页把标题交给 WorkspaceHeader（ChatConversation.tsx:9 / :159）。 */
  const activeTitle = useMemo(() => {
    const found = list.find((item) => String(item.id) === conversationId);
    return (found?.title ?? "").trim() || (conversationId ? "对话" : "新对话");
  }, [conversationId, list]);

  const visible = useMemo(() => items.slice(Math.max(0, items.length - windowSize)), [items, windowSize]);
  const visibleShellMessages = useMemo(
    () => toShellMessages(visible, conversationId ?? "artex"),
    [conversationId, visible],
  );

  return (
    <>
      {/* 官方页头（WorkspaceHeader，与 ChatConversation 同一件），不再自造标题栏。 */}
      {/* 页头右侧动作（官方 WorkspaceHeader 的 actions 扩展点）：
          一键回到「控制台对话」—— 那条路功能完整且已验证，作为兜底入口，不让用户被卡住。 */}
      <WorkspaceHeader
        actions={
          <Button
            aria-label="在控制台打开"
            onClick={() => navigate("/artex")}
            size="sm"
            variant="ghost"
          >
            在控制台打开
          </Button>
        }
        title={activeTitle}
      />
      <div className="cx-conversation" data-artifact="closed">
      {/* 会话列表面板：shell 模式 ⇒ 点行切外壳自己的 /artex-chat 路由。 */}
      <ArtexChatPanel mode="shell" />

      <div className="cx-conversation__main">
        {/* 转录列 / 内容层 / 底部渐隐锚 —— 结构与类名**逐条对齐**官方会话页
            （src/chat/ChatConversation.tsx:161-243），不再自造 .cx-page__body 与浮出条。 */}
        <div className="cx-thread" onScroll={handleScroll} ref={scrollRef}>
          <div className="cx-thread__content-wrap">
            <div className="cx-thread__content">
              <div className="cx-messages">
                {loading ? <RowSkeleton rows={4} /> : null}

                {error ? <p className="cx-thread__empty">出错了：{error}</p> : null}

                {items.length > visible.length ? (
                  <div className="cx-page__toolbar">
                    <Button onClick={() => setWindowSize((n) => n + 500)} size="sm" variant="surface">
                      显示更早的 {items.length - visible.length} 条
                    </Button>
                  </div>
                ) : null}

                {!loading && !error && visibleShellMessages.length === 0 ? (
                  <p className="cx-thread__empty">这个会话还没有消息。在下面输入框里说点什么。</p>
                ) : null}

                {visibleShellMessages.map((message) => (
                  <ChatMessage key={message.id} message={message} showActions={false} />
                ))}
                <div ref={bottomRef} />
              </div>
            </div>
            <div className="cx-thread__end-fade-anchor">
              <div aria-hidden className="cx-thread__end-fade" />
            </div>
          </div>
        </div>

        <div className="cx-conversation__composer">
          {/* 回到底部浮钮：官方 .cx-thread__to-bottom（ChatConversation.tsx:253-261），
              这是我此前自造的浮出条，现已删除。 */}
          <div className="cx-thread__to-bottom-anchor">
            <button
              aria-label="滚动到底部"
              className="cx-thread__to-bottom"
              data-visible={!nearBottom}
              onClick={jumpToLatest}
              type="button"
            >
              <CodexScrollToBottom size={20} />
            </button>
          </div>

          {/* 输入区用官方 Composer（自带权限/模型/发送钮那套官方控件），不再自写 Textarea+Button。 */}
          <Composer
            mode="conversation"
            onSend={(text) => void send(text)}
            onStop={() => {}}
            hideEffort
            hidePermission
            models={modelOptions.length > 0 ? modelOptions : undefined}
            placeholder="与 Codex 协作"
            selection={composerSelection}
            status={sending || running ? "streaming" : "idle"}
          />
        </div>
      </div>
      </div>
    </>
  );
}
