import { useMemo, useState } from "react";

import { useArtexQuery } from "@/api/artex";
import { PanelPortal } from "@/shell";
import { CodexRailScheduled, CodexRefresh, CodexSearch, CodexX } from "@/icons";
import { Button } from "@/ui";

import { EmptyState, RowSkeleton } from "./parts";

/**
 * 任务页（rail「任务」，外壳路由 /tasks）—— objective ② 的第一个「外壳原生渲染」页面。
 *
 * 与 /artex（把控制台 iframe 托管进来）不同：这一页是**外壳自己的代码**在画，
 * 数据由外壳直连 ARTEX API 取得（src/api/artex.ts）。之所以能做到，是三件事凑齐了：
 *   1. 后端 /api/* 的 CORS 是 *（server/server.go 的 cors()，实测 OPTIONS/GET 都带该头）；
 *   2. 访客（控制台）在握手后把 access token 经 codex-host:token 交给外壳（host-store）；
 *   3. 容器挂载时登记 API origin（= 访客 origin，生产态 http://127.0.0.1:8787）。
 *
 * 组件与样式全部复用外壳自己的：.cx-page__* / .cx-row*（pages.css）、@/ui 的 Button、
 * 以及 pages/parts 的 EmptyState/RowSkeleton/SearchField —— 不新造数值。
 * 面板侧用官方面板词汇 `.codex-panel__page-*`（见下），主面用 `.cx-page__*`，两套不混用。
 *
 * 数据契约（控制台 src/lib/types.ts:Task）只取本页用到的字段；其余透传不解释，
 * 避免外壳对业务模型做假设。
 */

interface ArtexTask {
  id: string;
  name?: string;
  description?: string;
  goal?: string;
  status?: string;
  pinned?: boolean;
  paused?: boolean;
  queued?: boolean;
  in_flight?: number;
  last_activity?: string;
  goals_total?: number;
  goals_met?: number;
}

interface TasksResponse {
  tasks?: ArtexTask[];
  active?: string;
}

/** ARTEX 任务状态 → 展示文案。未知状态原样显示，绝不猜。 */
const STATUS_LABEL: Record<string, string> = {
  pending: "待开始",
  queued: "排队中",
  running: "进行中",
  paused: "已暂停",
  done: "已完成",
  failed: "已失败",
  archived: "已归档",
};

function statusText(task: ArtexTask): string {
  if (task.in_flight && task.in_flight > 0) return "进行中";
  if (task.paused) return "已暂停";
  if (task.queued) return "排队中";
  const raw = (task.status ?? "").trim();
  if (!raw) return "未知";
  return STATUS_LABEL[raw] ?? raw;
}

function taskTitle(task: ArtexTask): string {
  const named = (task.name ?? "").trim();
  if (named) return named;
  const desc = (task.description ?? task.goal ?? "").trim();
  if (!desc) return "未命名任务";
  return desc.length > 80 ? desc.slice(0, 80) + "…" : desc;
}

function taskMeta(task: ArtexTask): string {
  const parts: string[] = [];
  if (typeof task.goals_total === "number" && task.goals_total > 0) {
    parts.push("目标 " + (task.goals_met ?? 0) + "/" + task.goals_total);
  }
  if (task.last_activity && task.last_activity.trim()) parts.push(task.last_activity.trim());
  return parts.join(" · ");
}

export function TasksRoute() {
  const { data, error, loading, reload } = useArtexQuery<TasksResponse>("/api/tasks");
  const [query, setQuery] = useState("");
  /** 选中项（官方：面板行选中 ⇒ 主面出详情；官方选中是 aria-pressed + data-selected）。 */
  const [selectedId, setSelectedId] = useState<string | null>(null);

  const tasks = data?.tasks ?? [];
  const filtered = useMemo(() => {
    const needle = query.trim().toLowerCase();
    if (!needle) return tasks;
    return tasks.filter((task) => {
      const haystack = (taskTitle(task) + " " + (task.description ?? "") + " " + (task.status ?? "")).toLowerCase();
      return haystack.includes(needle);
    });
  }, [tasks, query]);

  const selected = filtered.find((task) => task.id === selectedId) ?? null;

  return (
    <div className="cx-page" data-page="tasks">
      {/* 官方信息架构（出处 ScheduledPage.tsx:451 / :601）：
          `.cx-split[data-panel-layout="panel"]` 里，**列表进面板**（PanelPortal），**详情/hero 在主面**（`.cx-split__detail`）。 */}
      <div className="cx-split" data-panel-layout="panel">
        <PanelPortal>
          <div className="codex-panel__page-section">
            <div className="codex-panel__page-section-title">
              <div className="codex-panel__page-section-label">任务</div>
              <button aria-label="刷新任务" className="codex-panel__icon-button" onClick={reload} type="button">
                <CodexRefresh size={16} />
              </button>
            </div>

            {/* 面板搜索：官方 `.codex-panel__page-search`（SidebarPanel.tsx:309-337），
                不用主面的 SearchField —— 两处是不同的官方件。 */}
            <div className="codex-panel__page-search">
              <CodexSearch size={16} />
              <input
                aria-label="搜索任务"
                className="codex-panel__page-search-input"
                onChange={(event) => setQuery(event.target.value)}
                placeholder="搜索任务"
                type="text"
                value={query}
              />
              {query ? (
                <button aria-label="清空搜索" className="codex-panel__page-search-clear" onClick={() => setQuery("")} type="button">
                  <CodexX size={14} />
                </button>
              ) : null}
            </div>

            {loading ? <RowSkeleton rows={3} /> : null}

            <div className="codex-panel__page-list">
              {!loading && error ? (
                <div className="codex-panel__page-empty-row" role="status">
                  任务加载失败
                </div>
              ) : null}

              {!loading && !error && filtered.length === 0 ? (
                <div className="codex-panel__page-empty-row" role="status">
                  {query ? "没有匹配的任务" : "暂无任务"}
                </div>
              ) : null}

              {!loading && !error
                ? filtered.map((task) => (
                    <div className="codex-panel__page-row-wrap" key={task.id}>
                      <button
                        aria-pressed={task.id === selectedId}
                        className="codex-panel__page-row"
                        data-selected={task.id === selectedId ? "true" : undefined}
                        onClick={() => setSelectedId(task.id)}
                        type="button"
                      >
                        <span className="codex-panel__page-row-title">
                          {task.pinned ? "📌 " : ""}
                          {taskTitle(task)}
                        </span>
                        <span className="codex-panel__page-row-plan">
                          {statusText(task)}
                          {taskMeta(task) ? " · " + taskMeta(task) : ""}
                        </span>
                      </button>
                    </div>
                  ))
                : null}
            </div>
          </div>
        </PanelPortal>

        <aside className="cx-split__detail">
          {selected ? (
            <>
              <header className="cx-detail__header">
                <span className="cx-detail__title">{taskTitle(selected)}</span>
              </header>
              <div className="cx-detail__scroll">
                <div className="cx-detail__field">
                  <span className="cx-detail__label">状态</span>
                  <span className="cx-detail__value">{statusText(selected)}</span>
                </div>
                <div className="cx-detail__field">
                  <span className="cx-detail__label">目标</span>
                  <span className="cx-detail__value">{(selected.goal ?? "").trim() || "—"}</span>
                </div>
                <div className="cx-detail__field">
                  <span className="cx-detail__label">说明</span>
                  <span className="cx-detail__value">{(selected.description ?? "").trim() || "—"}</span>
                </div>
                {taskMeta(selected) ? (
                  <section className="cx-detail__field">
                    <span className="cx-detail__label">进度</span>
                    <span className="cx-detail__value">{taskMeta(selected)}</span>
                  </section>
                ) : null}
              </div>
            </>
          ) : (
            /* 主面 hero/空态：官方同一份 EmptyState（ScheduledPage.tsx:336-356 的 scheduledHero 同构：
               layout="page" + titleAs="h1"）。 */
            <EmptyState
              actions={
                error ? (
                  <Button onClick={reload} size="sm" variant="surface">
                    重试
                  </Button>
                ) : undefined
              }
              description={
                error
                  ? error.status === 0
                    ? "外壳还没拿到控制台的访问令牌（访客未附着或未登录）。"
                    : "ARTEX API 返回 " + error.status + (error.message ? "：" + error.message : "")
                  : query
                    ? "没有符合「" + query + "」的任务。"
                    : "左侧选中一个任务查看详情；在对话里下达目标会创建新任务。"
              }
              icon={CodexRailScheduled}
              layout="page"
              title={error ? "任务加载失败" : "任务"}
              titleAs="h1"
            />
          )}
        </aside>
      </div>
    </div>
  );
}
